quests[72336] = { id = 72336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeiten für die Erfahrung", sourceObjective = "<Dothenos betrachtet Euch wieder von oben bis unten.>\n\nHm. Na ja... Mode ist wohl Geschmackssache. Aber über die Ergebnisse lässt sich nicht streiten.\n\nEuer Können in der Schneiderei hat die Aufmerksamkeit unserer Meister erregt. Hier habt Ihr weitere Muster und Notizen, mit deren Hilfe Ihr sogar noch größeres Fachwissen erlangen könnt!", sourceObjectiveStatus = "unverified-source-field" }
quests[72337] = { id = 72337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großer Obsidianschlüssel", description = "Bringt mir einen zusammengesetzten Schlüssel.", sourceObjective = "Findet 1 zusammengesetzten Schlüssel.", progress = "Findet einen großen Obsidianschlüssel, dann können wir das volle Potenzial der Obsidianzitadelle aktivieren.", completion = "Dieser Schlüssel wird uns erlauben, mehr verlorene Geheimnisse der Zitadelle aufzudecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[72338] = { id = 72338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großer Obsidianschlüssel", description = "Bringt mir einen zusammengesetzten Schlüssel.", sourceObjective = "Findet 1 zusammengesetzten Schlüssel.", progress = "Findet einen großen Obsidianschlüssel, dann können wir das volle Potenzial der Obsidianzitadelle aktivieren.", completion = "Dieser Schlüssel wird uns erlauben, mehr verlorene Geheimnisse der Zitadelle aufzudecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[72339] = { id = 72339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Innovationsmaschine", description = "Tyr glaubte, dass die Innovationsmaschine für kommende Schlachten unentbehrlich sei.\n\nIhr habt Euch als würdig erwiesen und alle Herausforderungen überwunden, die Euch gestellt wurden. Ihr dürft das volle Potenzial der Maschine jetzt erwecken.", sourceObjective = "Setzt den neu abgestimmten Energiekern in die Innovationsmaschine ein.", completion = "Ihr habt Euch als würdig erwiesen und alle Herausforderungen überwunden, die Euch gestellt wurden.\n\nIhr dürft das volle Potenzial der Maschine jetzt erwecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[72354] = { id = 72354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Große Schatzkammer", description = "Über die Jahre hinweg haben die Aspekte und ihr Volk viele bemerkenswerte Artefakte und Waffen angesammelt. Die Aspekte haben die Konstruktion einer verzauberten Schatzkammer in Auftrag gegeben, um sie zu lagern, bis eine würdige Seele auf der Suche nach ihrem Inhalt eintrifft.\n\nIhr findet diese Schatzkammer innerhalb der Mauern der Bank. Vielleicht wird sie Euch einen Teil des uralten Schatzes der Aspekte gewähren, wenn Ihr Euren Eifer beweist.", sourceObjective = "Holt Euch eine Belohnung aus der Großen Schatzkammer.", progress = "Die Schatzkammer scheint zu wissen, wenn sich eine würdige Seele nähert. Ihr müsst Euch nicht fürchten, geht nur. Seht sie Euch an.", completion = "Ihr konntet Sie also doch öffnen? Sogar diese uralte Magie erkennt Eure Gabe für heldenhafte Taten an.\n\nIhr solltet regelmäßig bei der Schatzkammer vorbeischauen. Die Schätze in ihrem Inneren werden sich für Eure zukünftigen Kämpfe sicher als nützlich erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72358] = { id = 72358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaskade" }
quests[72360] = { id = 72360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederbelebung der Maschine", description = "Wie alle Vorrichtungen der Titanen birgt Tyrhold viel Wunder. Vor langer Zeit hat Hüter Tyr eine Maschine, genannt der Belebungskatalysator, für die Aspekte hinterlassen, um ihre Streitkräfte zu ermächtigen, sollte eine Schlacht unausweichlich werden. Er verfügt über immense Macht. \n\nAls ein Verbündeter der Drachen bieten sie Euch an, diese Maschine zu Eurer Unterstützung für die bevorstehenden Herausforderungen einzusetzen. Doch erst müsst Ihr ihn aufsuchen. der Katalysator ist eine große Gabe und wird einen gewaltigen Vorteil gegenüber Eurer Feinde darstellen, wenn Ihr in einsetzt.", sourceObjective = "Sucht den Belebungskatalysator.", completion = "Hüter Tyr wusste, dass ein Konflikt unausweichlich sein würde. Um seinen Freunden zu helfen, erschuf er den Belebungskatalysator.\n\nSeine Funktionsweise ist bemerkenswert. Gebt dem Katalysator ein Ausrüstungsteil, das Ihr auf Eurer Reise gefunden habt, und er wird es mit der Weisheit und Macht von Tyr persönlich erfüllen. Erfüllt genug Teile, dann werden vielleicht sogar Eure Fertigkeiten auf neue und einzigartige Weisen belebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72363] = { id = 72363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut im Machen, nicht im Verstehen", sourceObjective = "Ah, Drachenreiter. Willkommen zurück. Hier ist etwas Staub. Nein, ich weiß auch nicht wirklich, was es ist. Die Mystiker der Ohn'ir sagen, dass es Euch dabei helfen soll, mit den Ahnen Zwiesprache zu halten. Dass die Ahnen überall um uns herum sind. Hört sich optimistisch an, wenn Ihr mich fragt.\n\nIch kann nicht behaupten, dass ich die Ohn'iri verstehe. Die volle Wahrheit unter den Himmeln ist, dass ich es auch nicht möchte. Es sind gute Leute, aber sie sind seltsam. Beunruhigend. Aber auch Verbündete und sie haben mich darum gebeten, es Euch zu geben. Und Euch noch mehr zur Verfügung zu stellen, falls Ihr es wünscht. Und so mache ich das.", sourceObjectiveStatus = "unverified-source-field" }
quests[72364] = { id = 72364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zarizz" }
quests[72372] = { id = 72372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zähmung der Drachen...wesen", sourceObjective = "Das Blut des Drachen hat viele Wesen dieses Landes berührt. Obwohl man nicht mit allen von ihnen verhandeln kann, können sie dennoch treue Begleiter abgeben.\n\nEs gibt ein enges Band, das man schmieden muss, wenn man sich mit Drachen anfreunden möchte. Meinem Volk fällt es natürlich sehr leicht, aber ich kann Euch ein Buch geben, das Euch unsere Methoden beibringt.\n\nDanach liegt es an Euch, das nötige Band aufzubauen, das sie an Eurer Seite verweilen lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72373] = { id = 72373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft dem Abkommen: Die Jagd ist eröffnet", description = "Unsere Verbündeten auf den Ebenen von Ohn'ahra haben nach allen und jedem geschickt, die in diesen Landen jagen, um sie zu bitten, ihre Sache zu unterstützen.\n\nWährend Ihr Euren Bemühungen auf den Inseln nachgeht, stattet doch unseren Verbündeten in ihren Jagdlagern einen Besuch ab und helft Ihnen ein wenig aus.\n\nEs gibt viel zu tun. Trödelt nicht.", sourceObjective = "Helft den Maruuk bei einer Jagd auf den Dracheninseln. Führt Eure Bemühungen fort, dem Valdrakkenabkommen und seinen Verbündeten auf den ganzen Dracheninseln zu helfen.", completion = "Oh je. Das habt Ihr getan und seid unversehrt zurückgekehrt? Beeindruckend.\n\nBitte nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[72374] = { id = 72374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft dem Abkommen: Drachenfluchfestung", description = "Unsere Verbündeten brauchen einmal mehr Eure Unterstützung bei ihren Vorhaben auf den Inseln. In Valdrakken gehen Worte des Trostes um, die davon sprechen, wie Ihr geholfen habt, unsere Zukunft zu formen.\n\nZurück zum Geschäft.\n\nEine lauernde Bedrohung der Djaradin bewegt sich tief im Inneren des schwelenden Infernos der Drachenfluchfestung auf die Küste des Erwachens zu. Wir müssen diesen Vorstoß aufhalten.\n\nWir erwarten Eure Rückkehr, {name}.", sourceObjective = "Reist an die Küste des Erwachens und belagert die Drachenfluchfestung. Führt Eure Bemühungen fort, dem Valdrakkenabkommen und seinen Verbündeten auf den ganzen Dracheninseln zu helfen.", completion = "Das sind wundervolle Neuigkeiten! Das Abkommen wird froh sein, von Euren Taten zu hören.\n\nNehmt bitte dies als Zeichen unserer Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[72375] = { id = 72375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft dem Abkommen: Der Ruf der Inseln", description = "Eure Taten sind nicht unbemerkt geblieben.\n\nUnsere Verbündeten auf den ganzen Inseln gewährleisten die Sicherheit aller, die durch dieses Land reisen. Aber es gibt auch einige, die Eurer... Arbeit gerne ein Ende setzen würden, weil sie ihre Pläne stört.\n\nTut, was Ihr tun müsst, um den Schutz unserer Verbündeten sicherzustellen.", sourceObjective = "Führt Eure Bemühungen fort, dem Valdrakkenabkommen und seinen Verbündeten auf den ganzen Dracheninseln zu helfen.", completion = "Ah, Ihr seid zurück! Ich sollte nicht überrascht sein.\n\nBitte nehmt dies als Zeichen unserer Anerkennung.", sourceObjectiveStatus = "unverified-source-field" }
quests[72380] = { id = 72380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusammen sind wir nicht aufzuhalten", description = "{name}, Ihr müsst Alexstrasza und Nozdormu erzählen, was hier passiert ist.\n\nKhadgar und ich werden Euch in Kürze am Sitz der Aspekte treffen.", sourceObjective = "Kehrt zum Sitz der Aspekte zurück und informiert Alexstrasza darüber, was nach dem Sieg über Raszageth im Gewölbe der Inkarnationen geschehen ist.", completion = "Wir stellen uns vereint den Inkarnationen, {name}.\n\nGemeinsam werden diese Welt beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72381] = { id = 72381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenschuppenexpedition", description = "Unterstützt die Tortollaner, indem Ihr 3 Weltquests abschließt.", sourceObjective = "Schließt 3 Weltquests der Tortollaner ab.", sourceObjectiveStatus = "unverified-source-field" }
