quests[72395] = { id = 72395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Dracheninseln", sourceObjective = "Freund, Eure Unterstützung war unserer Gemeinschaft und unserem Volk eine gewaltige Hilfe. Wir haben einige zusätzliche Vorräte für Euch aufbewahrt, in der Hoffnung, dass Ihr uns weiterhin helfen könnt!", sourceObjectiveStatus = "unverified-source-field" }
quests[72396] = { id = 72396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fülle an Hörnern", description = "Viele unserer Erfindungen beruhen auf stabilen und federnden Materialien. Zum Glück sind Vorquinhörner die perfekte Grundlage vieler unserer modernsten Kreationen.\n\nUnd noch viel besser ist, dass es auf den Dracheninseln vor Vorquin nur so wimmelt! Es sollte eine einfache Aufgabe für Euch sein, einige federnde Hörner von den Vorquin für uns zu sammeln.", sourceObjective = "Sammelt 20 federnde Hörner von den Vorquin der Dracheninseln für Dothenos vom Valdrakkenabkommen.", progress = "Habt Ihr die Vorquinhörner gesammelt?", completion = "Unsere Ingenieure werden froh sein, mehr Materialien zu bekommen. Habt Dank für Euren Beitrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[72397] = { id = 72397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrichtung: Drachenschuppenbasislager", sourceObjective = "Trefft die wichtigen Versorger im Drachenschuppenbasislager.", progress = "Willkommen im Lager, {name}!", completion = "Ihr habt meinen Opa getroffen, oder?\n\nGlaubt nicht alle seine Geschichten... Er gibt gern mit der Familie an.", sourceObjectiveStatus = "unverified-source-field" }
quests[72398] = { id = 72398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fels und Stein", description = "Erdelementare auf den Dracheninseln bestehen aus verschiedenen Steinen und Mineralien. Unsere Schmiede sind völlig fasziniert von den einzigartigen Werkzeugen, die sie durch Verhüttung solcher Materialien herstellen können. Tatsächlich haben sie die letzten ihrer Proben verarbeitet.\n\nIch will ihnen wirklich nicht den Spaß verderben. Würdet Ihr vielleicht den Vorrat auffüllen?", sourceObjective = "Sammelt 15 irdene Proben von den Erdelementaren der Dracheninseln für Dhurrel von den Zentauren der Maruuk.", progress = "Habt Ihr genug irdene Proben von den Elementaren gesammelt?", completion = "Ah, die Schmiede werden über diese Proben erfreut sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[72399] = { id = 72399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Einsiedlergarten", description = "Unsere Eltern sagen immer, wir sollen die Gärten über Gelikyr nicht besuchen. Sie glauben, der Gärtner ist böse und gefährlich.\n\nAber das stimmt nicht. Er ist ein bisschen grummelig, aber wirklich nett! \n\nKeiner von uns war da oben, seit die Primalisten aufgetaucht sind. Jetzt ist es wirklich zu gefährlich. Aber ich hoffe, dem Gärtner geht es gut. Würdet Ihr bitte nach ihm sehen, wir können ihn ja nicht mehr besuchen.", sourceObjective = "Sprecht mit Szareth an der Schattenklippe.", completion = "Ich hoffe, Ihr habt keine meiner Pflanzen mit Euren ungeschickten Stampfern zertreten. Was wollt Ihr von mir?", sourceObjectiveStatus = "unverified-source-field" }
quests[72405] = { id = 72405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unerwartete Informantin", description = "Die ist eine streng geheime Mission, {name}.\n\nEs gab einen Einbruch.\n\nEin mächtiges historisches Artefakt wurde aus der Burg gestohlen... und die Bruderschaft der Defias scheint dafür verantwortlich zu sein. Wir haben einen der Diebe erwischt, aber der andere ist entkommen.\n\nMir gefällt das aber gar nicht, {name}... Mein Bauchgefühl sagt mir, dass da noch mehr dahintersteckt.\n\nIch habe... eine Expertin für die Bruderschaft gerufen. Trefft uns im Keller des Gasthauses \"Zur Höhle des Löwen\" in Goldhain.", sourceObjective = "Trefft Mathias Shaw im Keller des Gasthauses \"Zur Höhle des Löwen\".", progress = "Wir müssen um jeden Preis zurückholen, was aus der Burg gestohlen wurde.", completion = "Meine wenigen Begegnungen mit Vanessa sagen mir, dass sie kein Interesse an den Banditen der Bruderschaft der Defias hat. Für sie stand die Bruderschaft dafür, die Geknechteten zu unterstützen... diejenigen, die in Sturmwind abgehängt worden waren.\n\nDavor habe ich Respekt.\n\nDoch der Großteil ihrer Bruderschaft überfällt weiterhin unschuldige Reisende. Das ist keine Revolution, sondern Wegelagerei.\n\nAngeblich bemüht sie sich, das zu verhindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[72406] = { id = 72406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrichtung: Valdrakken", sourceObjective = "Trefft die wichtigen Versorger des Abkommens in Valdrakken.", completion = "Im Namen des Valdrakkenabkommens freuen wir uns darauf, mit Euch zu arbeiten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[72407] = { id = 72407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfolgsgetränkt", description = "Die Fischer unseres Stammes haben ständig mit durchnässten Taschen und Stiefeln zu kämpfen. Und in letzter Zeit mischen auch noch die Flussbestien die Angelplätze auf und richten noch mehr Chaos an.\n\nDie Haut von Flussbestien ist ziemlich glatt und wasserabweisend. Vielleicht können wir zwei Fliegen mit einer Klappe schlagen. Wenn Ihr helfen könntet, die übermäßige Flussbestienpopulation zu reduzieren, und ihre Häute mitbringt, würdet Ihr unseren Fischern einen großen Gefallen tun.", sourceObjective = "Sammelt 18 wasserdichte Bälge von den Flussbestien der Dracheninseln für Temnaayu von den Tuskarr von Iskaara.", progress = "Habt Ihr ein paar wasserdichte Bälge gefunden?", completion = "Ich bin sicher, diese Bälge werden unsere Ausrüstung vor weiterem Wasserschaden schützen. Habt Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[72408] = { id = 72408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Blick in die Vergangenheit", description = "In diesem Fall glaube ich Vanessa. Ich denke nicht, dass sie weiß, was das Drachenfeueramulett ist. Ein Teil der Geschichte mit Onyxia ging an die Öffentlichkeit, aber nicht alles.\n\nVielleicht wisst selbst Ihr es nicht.\n\nIch werde Euch beiden alles erklären.", sourceObjective = "Sprecht mit Shaw im Keller des Gasthauses \"Zur Höhle des Löwen\" in Goldhain, um die Geschichte des Drachenfeueramuletts zu hören.", progress = "<Vanessa mustert Euch.>", completion = "Wir alle kennen jeweils unterschiedliche Versionen der Vergangenheit, nicht wahr?\n\nOb da eine Drachenfrau ein magisches Amulett hatte, ist mir egal. Man kann nicht alles auf Gedankenkontrolle schieben.\n\nDie Adligen verachteten das gemeine Volk bereits. Die Steinmetzgilde hätte niemals eine Bande Banditen werden und die Bruderschaft der Defias gründen müssen, wenn sie nicht gewesen wären.", sourceObjectiveStatus = "unverified-source-field" }
quests[72409] = { id = 72409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlimme alte Erinnerungen", description = "Was auch immer hier los ist, es gefällt mir nicht. Wir können es wirklich nicht gebrauchen, dass die Macht dieser Drachenfrau wieder alle verderbt.\n\nWer auch immer das getan hat, muss viel über Onyxia wissen. Shaw hat einen gewissen... Reginald Windsor erwähnt. Er war der Einzige, der Lady Prestor verdächtigte. Vielleicht haben seine Freunde in der Brennenden Steppe ja mehr von seinen Informationen.\n\nSie muss Verbündete gehabt haben. Alles, was uns zu Leuten in ihrer Nähe führt, würde helfen.\n\nKönnt Ihr dieser Sache nachgehen?", sourceObjective = "Sprecht mit dem struppigen John in Morgans Wacht in der Brennenden Steppe.", progress = "Ich sitze schon wieder auf dem Trockenen... Warum passiert mir das ständig?", completion = "Ach, Windsor...", sourceObjectiveStatus = "unverified-source-field" }
quests[72410] = { id = 72410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viele Zangen, spitze Nadeln", description = "Uns gehen bald die Nähnadeln aus. Diese verflixten Dinger brechen ständig ab!\n\nEinige spitze Teile der Scythiden in der Gegend könnten gut als Ersatz herhalten.", sourceObjective = "Sammelt 10 spitze Zangen von den Scythiden der Dracheninseln für Gnoklin Quirkspule von der Drachenschuppenexpedition.", progress = "Habt Ihr einige spitze Teile gefunden, um unsere Nadeln zu ersetzen?", completion = "Großartig! Jetzt können die Schneider endlich weiterarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[72411] = { id = 72411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gründe einer Rebellion", description = "Schön, Euch wiederzusehen, {name}! Alexstrasza glaubt trotz Eures Erfolgs nicht daran, dass wir die Rebellen mit Gewalt wirklich aufhalten können.\n\nUm andere Optionen abzuwägen, hat Alexstrasza Maldra Flammenzunge herberufen, damit sie über die Rebellion sprechen kann und darüber, was sie dazu bewegt hat, ihr anzuführen.\n\nEs könnte ganz nützlich sein, an dem Gespräch teilzuhaben und zu hören, was Maldra zu sagen hat. Sie werden sich unter uns auf der zweiten Ebene des Sitzes der Aspekte treffen, um neugierigen Rebellenaugen und -ohren vorzubeugen.", sourceObjective = "Hört dem Gespräch zwischen Alexstrasza und Maldra Flammenzunge zu.", completion = "Ich habe herausgefunden, dass die Rebellen eine ganze Menge Bomben unter dem Valdrakkenaquädukt anhäufen! Wir müssen sie aufhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[72412] = { id = 72412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Unterbrechung", description = "Ich konnte in den Schuppenwachthöhlen ein Rebellenlager infiltrieren. Es wirkte wie jedes andere Lager, allerdings kamen regelmäßig abgedeckte Wägen hinein.\n\nIrgendwann konnte ich mich dort hinschleichen, wo sie die Wagen abladen. Die Rebellen schaffen jede Menge Bomben heran, aber es wird noch schlimmer!\n\nSie stapeln sie an einer Säule, direkt unter dem Aquädukt von Tyrhold.\n\nTrefft mich dort unten, dann halten wir sie gemeinsam auf!", sourceObjective = "Trefft Erima bei den Schuppenwachthöhlen.", completion = "Wir scheinen noch rechtzeitig gekommen zu sein, {name}. Setzen wir dem ein Ende, bevor das Aquädukt zerstört wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[72413] = { id = 72413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unüberbrückbare Differenzen", description = "Ich wünschte, wir hätten nie gegen andere Drachkin zur Waffe greifen müssen, {name}. Wir sollten Verbündete sein, keine Feinde. Leider hat ihr Anführer, Aufwiegler Zoralek, uns diese Entscheidung abgenommen, als er das Aquädukt bedroht hat.\n\nKämpft Euch ins Innere der Höhle vor und haltet Aufwiegler Zoralek um jeden Preis auf, bevor er die Bomben zünden kann. Bringt mir dann seinen Zünder, damit wir ihn sichern können. Wenn das erledigt ist, können die Eidschuppen die Bomben sicher entfernen.", sourceObjective = "Tötet Aufwiegler Zoralek und holt Euch den Zünder.", progress = "Konntet Ihr Zoralek aufhalten? Ist das Aquädukt außer Gefahr?", completion = "Ihr habt das Aquädukt für Valdrakken und die Lebensbecken gerettet, indem Ihr Zoralek aufgehalten und seinen Zünder an Euch genommen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72414] = { id = 72414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine Gefangenen!", description = "Wenn Alexstrasza den Grund für diese Rebellion wirklich erfahren will, müssen wir die Rebellen anhören.\n   \nDafür müssen wir die Rebellen in Gewahrsam nehmen, die uns töten wollen. Na ja, die Euch töten wollen. Das ist deutlich schwerer und gefährlicher, als Gewalt anzuwenden.\n\nAber ich habe das selbst schon erlebt, als ich die Rebellen verlassen habe. Orian Dunkelwasser hat einen Zauber gewirkt, der mich komplett gebunden hat. Der hat sehr gut funktioniert, aber ich habe aufgepasst.\n\nIch habe einen Ring mit diesem Zauber erfüllt. Ihr könnt sie damit sicher binden. Das sollte zumindest funktionieren!", sourceObjective = "Nutzt Maldras Ring der Bindung, um 8 Rebellen in Gewahrsam zu nehmen.", completion = "Diese Methode mag schwieriger sein, aber jeder Rebell, den wir gefangen nehmen, anstatt ihn zu töten, ist ein Schritt zum Ende der Gewalt... und ein gerettetes Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[72415] = { id = 72415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufrührerische Schriften", description = "Die Rebellen scheinen eine Menge Schilder und Flugblätter in der Höhle zu haben. Vermutlich wollen sie damit alle dazu bewegen, ihrem Ziel zu folgen, und sie für den Kampf motivieren.\n\nEs ist nicht leicht, eine große Gruppe ohne gemeinsames Ziel zusammenzuhalten, wenn man nicht ständig Verstärkung bekommt... vor allem, wenn man auf so abscheuliche Methoden wie das Bombardieren von Zivilisten und das Zerstören von Wasserquellen zurückgreift.\n\nHolen wir uns etwas von ihrer Propaganda. Das könnte uns einiges über ihre Denkweise verraten oder darüber, wer ihnen ihre Denkweise vorgibt.", sourceObjective = "Sammelt 5 Exemplare der Rebellenpropaganda.", progress = "Konntet Ihr ein paar Proben ihrer Schriften ergattern?", completion = "Der größte Teil davon scheint von Anstifterin Belaphon geschrieben worden zu sein. Ich habe sie während meiner Zeit bei den Rebellen einmal getroffen. Wenn wir sie finden, können wir sie vielleicht davon abhalten, so viel Zorn zu predigen!\n\nWährenddessen kann ich noch einmal alles durchsehen. Vielleicht nutzen sie ja immer noch irgendwelche Verschlüsselungen aus meiner Zeit und wir kommen so an zusätzlich Informationen. Gute Arbeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[72416] = { id = 72416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorübergehende Unterkünfte", description = "Wir haben die gefangenen Rebellen zum Stahlklippenbollwerk geschickt. Die Eidschuppen, die Stadtwache von Valdrakken, sind dort stationiert.\n\nBei so vielen Wachen werden sie es kaum schaffen, Schaden anzurichten oder gar zu flüchten.\n\nBegebt Euch dorthin, dann werden wir sehen, wie wir weiter vorgehen, um diese Rebellion endgültig zu beenden.", sourceObjective = "Begebt Euch zum Stahlklippenbollwerk.", completion = "Danke, dass Ihr gekommen seid, {name}. Ich bin hier, um von den Gefangenen zu erfahren, warum sie gegen die Drachen rebellieren. Schließt Euch mir an, dann wollen wir sehen, was sie zu sagen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[72417] = { id = 72417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hartnäckige Dissidenten", description = "Ich möchte, dass diese Rebellion mit möglichst wenig Gewalt zu Ende geht. Dafür muss ich verstehen, worin die Ursachen für diese Rebellion liegen.\n\nDie Rebellen haben eine klare Abneigung gegen die Aspekte und die Drachenschwärme entwickelt. Und obwohl wir Valdrakken gewaltsam verteidigen mussten, hat das der Rebellion kein Ende gesetzt.\n\nIch hätte gern, dass Ihr mit den Gefangenen sprecht und sie fragt, warum sie rebelliert haben. Ich werde Euch begleiten, um mir ihre Gründe anzuhören.", sourceObjective = "Fragt 5 Drachkin nach den Gründen für ihre Rebellion.", completion = "Ich kann vielleicht einige ihrer Gründe nachvollziehen, aber auf keinen Fall ihre Gewaltbereitschaft. Immerhin habe ich nun einen neuen Blickwinkel darauf, warum sie sich eine Veränderung wünschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72418] = { id = 72418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meinungsbild", description = "Das war die reinste Erleuchtung. Die Rebellen, die wir befragt haben, waren deutlich gesprächiger, als ich es erwartet hätte.\n\nIch habe mir schon eine Meinung gebildet, aber was haltet Ihr von ihren Beschwerden?\n\nIhr seid weder Drache noch Drachkin, was Euch eine gewisse Objektivität verleiht.", sourceObjective = "Besprecht die Beschwerden der Rebellen mit Alexstrasza.", progress = "Steckt hinter den Aussagen der Drachkin Wahrheit oder reine Pflichtvernachlässigung?", completion = "Ich werde Euren Rat berücksichtigen. Nochmals vielen Dank für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[72419] = { id = 72419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit der Klippschaft aufräumen", description = "{name}! Maldra hat mithilfe von Verschlüsselungen aus ihrer Zeit als Rebellin die Propaganda durchgesehen, die Ihr besorgt habt.\n\nSie ist auf eine versteckte Botschaft gestoßen, die sie in ein anderes Rebellenlager geführt hat, in dem Belaphon für Aufruhr sorgt, wo sie nur kann.\n\nMaldra und Erima sind bereits dort. Stoßt zu ihnen, dann wollen wir sehen, ob wir dieser Rebellion nicht endlich ein Ende setzen können!", sourceObjective = "Trefft Maldra und Erima an den Rebellischen Klippen.", completion = "Laut den Informationen, die Maldra durch die alten Verschlüsselungen gefunden hat, strömen die Rebellen aus Schuppenwacht und anderen Orten hierher, {name}. Es sind mittlerweile viel zu viele Rebellen, um Belaphon ohne Eure Hilfe aufzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[72420] = { id = 72420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krach und Versöhnung", description = "Hauptmann Drine hat mich darüber informiert, dass Alexstrasza die Sache so friedlich wie möglich abgewickelt haben möchte. Ich habe auch gehört, dass Alexstrasza darüber nachdenkt, den Drachkin mehr Rechte zu gewähren. Oder sogar die Freiheit.\n\nAnstatt uns durch all diese Rebellen zu kämpfen, obwohl bereits Frieden am Horizont zu sehen ist, sollten wir besser die Botschaft verbreiten! Lasst die Drachkin wissen, dass die Dinge sich ändern. Vielleicht legen einige von ihnen ihre Waffen nieder oder beschließen, die Rebellion zu verlassen.\n\nSeid jedoch darauf gefasst, die zu bekämpfen, die darauf bestehen.", sourceObjective = "Informiert 12 Drachkin über Alexstraszas geplante Änderungen.", progress = "Denkt daran, dass jeder überzeugte Drachkin ein gerettetes Leben bedeutet.", completion = "Wie schön, dass so viele den Kampf aufgegeben haben. Schade um die, die das nicht konnten, aber hättet Ihr mir vorher erzählt, dass der Großteil eines Rebellenlagers die Waffen niederlegen würde, hätte ich Euch für verrückt erklärt. Alexstrasza wird sehr zufrieden sein, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[72421] = { id = 72421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit der Feder zur Macht", description = "{name}, wir müssen die Federkiele lang genug davon abhalten, die Rebellen aufzustacheln, um zu ihnen durchdringen zu können.\n\nSie scheinen sich durch den leuchtenden Stab ihrer Anführerin, Belaphon, fast zu verselbstständigen. Sammelt so viele ein, wie Ihr könnt, damit sie ihre Worte nicht weiter wiedergeben.\n\nWenn die außer Gefecht gesetzt sind, konfrontieren wir Belaphon direkt, aber wir dürfen nicht zulassen, dass die Federkiele weiterhin solche Botschaften verbreiten.", sourceObjective = "Sammelt 6 verzauberte Federkiele.", progress = "Wie viele Federkiele habt ihr gefunden, {name}?", completion = "Hätten wir diese Federkiele nicht eingesammelt, würden sie nach wie vor die Drachkin aufwiegeln und uns stünden noch mehr Rebellen im Weg. Danke, dass Ihr das aufgehalten habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72422] = { id = 72422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stoppt die Pressen", description = "Es ist so weit, {name}. Belaphon ist diejenige, die die Ideologie hinter der Rebellion verbreitet. Wenn wir sie aufhalten können, erleben wir das Ende der Rebellion.\n\nVermutlich müsst ihr sie zuerst schwächen, aber versucht dann, sie mit meinem Ring zu binden. Wenn sie sich ergibt, bringen wir sie zu Alexstrasza.\n\nIch kann mir vorstellen, dass die Königin der Drachen ihr so einiges zu sagen hat, wenn sich die beiden begegnen.", sourceObjective = "Besiegt Anstifterin Belaphon.", completion = "Habt Dank, {name}! Ihr habt uns von Anfang an geholfen, diese Rebellion zu bekämpfen. Valdrakken ist nun in Sicherheit, und ich werde dafür sorgen, dass den Drachkin der Respekt entgegengebracht wird, den sie verdienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72423] = { id = 72423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Sturm überstehen", description = "Ah, Ihr kommt genau rechtzeitig! Wir haben gehört, dass die Zentauren der Nokhud mächtige, gefährliche Waffen mit Sturmverzauberungen haben. Wir würden unseren Verzauberern gerne einige Exemplare bringen, damit sie sie studieren können.\n\nIm schlimmsten Fall können wir die Waffen immer noch entladen und für gute Zwecke einsetzen.", sourceObjective = "Sammelt 12 Sturmwaffen von den Zentauren der Nokhud auf den Dracheninseln für Temnaayu von den Tuskarr von Iskaara.", progress = "Habt Ihr Waffen gefunden, die wir studieren können?", completion = "Zu wissen, dass diese Waffen nicht mehr in zerstörungswütigen Händen liegen, gibt uns ein Gefühl von Sicherheit, und wir können endlich anfangen, diese Verzauberungen zu untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72424] = { id = 72424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach etwas Bestimmtem", description = "<Der struppige John sieht Euch müde an.>\n\nIhr habt den alten Worg also erledigt, was? Dann seid Ihr aber der größte, stärkste Mensch, der mir seit dem alten Windsor begegnet ist.\n\n<Der struppige John seufzt.>\n\n...Ja? Was lungert Ihr noch hier herum? Bringt demjenigen, der Euch überhaupt hergeschickt hat, was Ihr gefunden habt!", sourceObjective = "Kehrt zu Shaw im Keller des Gasthauses \"Zur Höhle des Löwen\" zurück.\n\nBereitgestellter Gegenstand:", completion = "Den struppigen John gibt es noch, was? Es ist schon eine Weile her, dass ich Agenten losgeschickt habe, um nach ihm zu sehen. Alles in allem ist er schon ein guter Mann.\n\nAlso, was steht jetzt in diesen Notizen? Hmmm... Clessington?", sourceObjectiveStatus = "unverified-source-field" }
quests[72426] = { id = 72426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das neue Anwesen der Clessingtons", description = "Hervorragend, {name}. Endlich etwas, das uns weiterhilft.\n\nGraf Clessington ist Mitglied des Adelshauses und ein mächtiger Magier. Seit Anduin der Korruption in Sturmwind einen Riegel vorgeschoben hat, sind es harte Zeiten für ihn.\n\nIch würde ihm zutrauen, dass er hier seine Finger im Spiel hat.\n\nEr hat vor Kurzem ein altes Anwesen im Dämmerwald gekauft. Ich werde meine Leute kontaktieren und sehen, was ich noch herausfinden kann. Ihr und Vanessa solltet Euch das Anwesen ansehen.", sourceObjective = "Untersucht das Anwesen in Rabenflucht im Dämmerwald.", completion = "Ich entschuldige mich vielmals für das Verhalten meiner \"Bediensteten\".\n\nWobei das eigentlich nie meine waren. Es sind die meines Vaters. Sie sollen mich wahrscheinlich auf Distanz halten, während er etwas Schlimmes tut.\n\nIch hatte gehofft, dass es so weit nicht kommen würde. Es tut mir so leid. Bitte lasst mich Euch dabei helfen, ihn aufzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[72427] = { id = 72427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belebte Infusion", description = "Ich habe heute eine einfache Bitte an Euch.\n\nDen Alchemisten geht eine Zutat aus, die sie für ein besonders heikles Gebräu brauchen. Das Kraut ist aber leicht zu finden. Ihr müsst nur einige aggressive Pflanzen finden, denen Ihr Proben entnehmen könnt. Fühlt Ihr Euch dem gewachsen?", sourceObjective = "Sammelt 13 stachelige Blätter von den Peitschern der Dracheninseln für Dhurrel von den Zentauren der Maruuk.", progress = "Habt Ihr die Kräuter?", completion = "Naja, nicht jede Jagd kann die alleraufregendste sein. Wir danken Euch trotzdem für die Proben, die Ihr gesammelt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72428] = { id = 72428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flunkerbunker", description = "Es ist kein Geheimnis, dass die Flunker dieses Landes eine Faszination für Edelsteine, Juwelen und alles, was glitzert, aufweisen. Erst vor Kurzem fand ich einen sehr wertvollen Edelstein in Flunkerkot!\n\nEs ist vielleicht nicht die angenehmste Arbeit, aber anscheinend sammeln die Flunker Wertgegenstände nicht nur, sie fressen sie auch.", sourceObjective = "Sammelt 20 stinkende Edelsteine von den Flunkern auf den Dracheninseln für Gnoklin Quirkspule bei der Drachenschuppenexpedition.", progress = "Konntet Ihr einige Edelsteine finden?", completion = "Diese Edelsteine riechen wirklich nicht sehr angenehm... Wir sollten sie besser gleich säubern.", sourceObjectiveStatus = "unverified-source-field" }
quests[72429] = { id = 72429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrichtung: Maruukai", description = "<Als Sansok Khan seufzt, spricht Okir für sie.>\n\nDas Volk der Maruuk hat sich nicht gegen Außenseiter verschworen, aber alle möglichen Verbündeten müssen sich uns gegenüber dennoch beweisen. Während Ihr die Klans trefft und unterstützt, werden sich Geschichten über Eure Taten bald herumsprechen.\n\nAuf der unteren Ebene des Krutals auf dem Hügel könnt Ihr eine der Töchter der Khanam Matra finden. Sie kann Euch sagen, wie es um Euren Ruf bei unserem Volk steht. Vergesst nicht, Euch bei ihr vorzustellen.", sourceObjective = "Trefft die Hüterin des Ruhms und den ruhmreichen Rüstmeister in Maruukai.", progress = "Ich freue mich darauf, Euren Beitrag für die Maruuk zu verfolgen.", completion = "Ich freue mich darauf, Euren Beitrag für die Maruuk zu verfolgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72430] = { id = 72430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missetaten in Mondbruch", description = "Mondbruch? Was treibt dieser Graf Clessington in meinem Zuhause?!\n\nBestimmt nichts Gutes. Ich gebe Shaw Bescheid.\n\n<Vanessa wirft Cecilia Clessington einen Blick zu.>\n\nDie könnte eine gute Geisel abgeben. Nehmen wir das reiche Mädchen auch mit.\n\nWir sehen uns dort.", sourceObjective = "Trefft Euch mit Vanessa und Shaw in Mondbruch in Westfall.", completion = "Warum ist es hier... so leer?", sourceObjectiveStatus = "unverified-source-field" }
quests[72431] = { id = 72431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein hungriges Vermächtnis", description = "Ich war eine ganze Weile nicht mehr zu Hause.\n\nEtwas stimmt hier nicht. Meine Leute sollten hier sein.\n\nIch gehe rein... hätte aber nichts gegen etwas Verstärkung.\n\n...Ich hätte nie so lang wegbleiben dürfen.", sourceObjective = "Untersucht das Versteck der Defias in Mondbruch mit Vanessa.", completion = "Wie können sie es wagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[72432] = { id = 72432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur die feinsten Schläger", description = "Diese \"Bediensteten\" meines Vaters haben uns angegriffen, sobald wir ankamen.\n\nDas sind ganz gewiss nicht die freundlichen Diener, die ich als Kind hatte. Das sind Auftragsmörder.\n\nWenn mein Vater wirklich plant, was ich glaube... Das dürfen wir nicht zulassen. Sie werden alle töten, die sich ihnen in den Weg stellen.\n\n<Cecilia erschaudert.>\n\nWenn es hart auf hart kommt...", sourceObjective = "Tötet 16 Bedienstete der Clessingtons im Versteck der Defias in Mondbruch.", completion = "Ich hoffe, dass ihre Seelen Frieden finden. Ich habe das so nicht gewollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72434] = { id = 72434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rubinlebensschrein-Schleife", description = "Sie sagen, ich bin noch nicht groß genug, um einige dieser Strecken zu fliegen.\n\nAber ich kann anderen dabei zusehen. Ihr solltet das Rennen fliegen! Dann kann ich Euch zusehen!", sourceObjective = "Schließt die Rubinlebensschrein-Schleife ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[72435] = { id = 72435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrichtung: Iskaara", description = "Willkommen in Iskaara.\n\nGeschichten über Eure Taten in Brackenfell haben bereits unser Volk erreicht. Ihr habt schon viele von uns getroffen und es gibt noch viele andere, die gerne Wissen und Waren mit Euch austauschen würden.\n\nBitte, nehmt Euch einen Moment, um einige der freundlichen Gesichter in Iskaara kennenzulernen. In unserer Gemeinschaft hilft man sich gegenseitig, so viel Ihr uns also zu bieten habt, so viel haben unsere Leute Euch im Gegenzug anzubieten.", sourceObjective = "Lernt einige Händler mit wertvollen Waren kennen.", progress = "Wir haben uns gegenseitig so viel zu bieten.", completion = "Ich hoffe, Ihr habt eine angenehme Zeit in Iskaara.\n\nWie Ihr wisst, sind viele von uns gute Handwerker und Händler. Ich würde vorschlagen, dass Ihr ein wenig herumfragt und herausfindet, was mein Volk alles zu bieten hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[72438] = { id = 72438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absichten der Tarasek", description = "Als die Tarasek die Macht der Primalisten annahmen, haben sie viele uralte Schriftrollen und Folianten gestohlen, um sie mit ihrer neugefundenen Magie zu kombinieren. Wir werden Hilfe brauchen, wenn wir diese Schriftrollen wiedererlangen wollen.", sourceObjective = "Sammelt 15 drakonische Schriftrollen von den Tarasek der Dracheninseln für Dothenos vom Valdrakkenabkommen.", progress = "Habt Ihr ein paar der Schriftrollen besorgt?", completion = "Vielen Dank, dass Ihr uns geholfen habt, dieses wertvolle Wissen wiederzuerlangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72440] = { id = 72440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eifer ist Silber", sourceObjective = "Begebt Euch mit der Hilfe der Aspekte in Tyrs Grabmal.", progress = "Ich möchte den Mann nicht mit meiner... Präsenz erschrecken. Vielleicht sprecht Ihr ihn besser zuerst alleine an.", completion = "Dieser Ort ist ein Monument für Tyrs Vermächtnis. Wir müssen Vorsicht und Ehrfurcht walten lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72441] = { id = 72441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einbruch in das Grabmal", description = "Irgendetwas hat kürzlich das titanische Verteidigungssystem der Grabstätte aktiviert. Ich habe hier zuvor keine Titanenkonstrukte gesehen.\n\nAls ich aus dem Grabmal ausgesperrt wurde, habe ich den Grund für ihr Erscheinen erforscht. Vielleicht hat Eure Mission das bewirkt.\n\nWenn wir weitergehen wollen, müssen wir die neue Verteidigung deaktivieren. Die leuchtenden Kugeln an den Türen könnten der Schlüssel dafür sein. Wenn sie nur nicht beschädigt wären...", sourceObjective = "Deaktiviert die Titanenkugeln am Eingang des Grabmals.", completion = "Eure Mission hat meinen Glauben neu entfacht. Was müssen wir tun, um Tyr wiederherzustellen?", sourceObjectiveStatus = "unverified-source-field" }
quests[72442] = { id = 72442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Überreste Tyrs", description = "So, wie Nozdormu die Macht in der Schuppe spüren konnte, kann ich Tyr hier spüren. Er steckt im Fundament dieses Ortes.\n\nDie anderen Konstrukte können das vermutlich auch fühlen. Sie müssen hergekommen sein, als Tyr neu geformt wurde. Wir müssen auf der richtigen Spur sein.\n\nFalls noch etwas von seiner Präsenz übrig ist, sollte die Schuppe sie mithilfe dieser Schalttafel sammeln können. Die Konstrukte könnten unsere Bemühungen um Tyrs letzte Erinnerungen als Versuch verstehen, sie zu zerstören. \n\nHaltet sie fern, falls sie erwachen.", sourceObjective = "Verteidigt Hüter Koranos gegen die Konstrukte im Grabmal.", completion = "Diese alte Schalttafel war der großen Aufgabe nicht gewachsen, aber unsere Hartnäckigkeit hat sich bezahlt gemacht.\n\nDie Schuppe hat irgendetwas, aber ich bin mir nicht sicher, was es ist.\n\nIch bin mir... unschlüssig, ob ich mit \"irgendetwas\" zu Alexstrasza zurückkehren möchte. Die Schuppe könnte aufgrund des Versagens der Konsole lauter Unsinn enthalten. Oder sie könnte genau das beinhalten, was wir brauchen.\n\nVielleicht könnte eine weitere Schalttafel uns über ihre Inhalte aufklären?", sourceObjectiveStatus = "unverified-source-field" }
quests[72443] = { id = 72443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrs Fall", sourceObjective = "Benutzt die Titanenschalttafel, um Tyrs letzten Erinnerungen beizuwohnen.", progress = "Es gibt vieles, was wir noch nicht über Tyr wissen.", completion = "Selbst in seinen letzten Momenten bewies er so viel Edelmut. Zakajz benutzte die Drachen, um ihn zu verspotten... Aber wusste Tyr wirklich, dass sie ihn verraten würden? Und was ist mit Alexstrasza? \n\nDas wäre ein schwerer Schlag für sie... \n\nWenn Tyr nicht erweckt werden kann, müssen sie es vielleicht auch nicht erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[72444] = { id = 72444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hauch von Silber", description = "Tyrs letzte Erinnerungen sind in unseren Händen. Diese Verantwortung dürfen wir nicht auf die leichte Schulter nehmen.\n\nBringen wir die Silberschuppe zu Nozdormu in Tyrhold. Wir werden versuchen, ihn mit der Schalttafel dort zu erwecken. \n\nWenn er wiederhergestellt ist, wird es einiges zu besprechen geben.", sourceObjective = "Entkommt aus dem Grabmal und kehrt zu den Aspekten bei Tyrhold in Valdrakken zurück.", progress = "Wir tun alles, was nötig ist, um Tyr wiederherzustellen.", completion = "Ich danke Euch, {name}.\n\nIch bin etwas... enttäuscht, dass die Silberschuppe nicht die Antwort war.\n\nWir müssen uns vielleicht auf eine Zukunft ohne Tyr einstellen.\n\nIch habe immer noch Hoffnung, dass wir die Scheibe finden und Tyr wiederherstellen können. Und ein Teil von mir glaubt, dass wir die Ewigen... und die Inkarnationen... aus eigener Kraft besiegen können. \n\nEinige Wege, so dunkel sie auch sein mögen, sind dazu bestimmt, beschritten zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[72445] = { id = 72445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Nordhain", description = "Vanessa sorgt sich um ihre Leute und hat Besseres verdient als einen Haufen Banditen. Ich bin froh, dass sie diese hinter sich lässt.\n\nAls Meisterspion bin ich ziemlich erleichtert darüber.\n\nNun wenden wir uns Nordhain zu. Dort können aus einfachen Bauern Helden werden. Vielleicht nahm Eure Reise ja auch in dieser Abtei ihren Anfang?\n\nAbgesehen davon ist es eine gut zu verteidigende Position, aus der man Sturmwind angreifen könnte. Wir dürfen nicht zulassen, dass sie fällt!\n\nSchnell, nach Nordhain!", sourceObjective = "Trefft Euch mit Vanessa, Cecilia und Shaw in Nordhain.", completion = "Wir müssen helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[72446] = { id = 72446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist ihr Problem?", description = "Schön, Euch wieder zu sehen, <Rekrut/Rekrutin>. Ich wünschte nur, die Umstände wären andere.\n\nWas immer dieser \"Einfluss\" auch sein mag... Alle, die auch nur im Entferntesten Groll hegen, vergießen jetzt Blut deswegen!\n\nUnd dann haben wir da noch die Banditen der Defias und die angeheuerten Schläger! In dieser Situation würde das nur zu noch mehr Chaos führen, wenn wir weitere Soldaten aus Sturmwind hineinschicken.\n\nSoweit ich es mitbekommen habe, könnt Ihr den meisten dieser Leute wieder Vernunft beibringen. Wenn sie noch weiterkämpfen, obwohl sie wieder bei Sinnen sind... dann tut, was Ihr tun müsst. Sie hatten ja die Wahl.", sourceObjective = "Verteidigt Nordhain.", progress = "Ich habe während meiner Zeit als Ausbilder schon so einiges gesehen... aber das hier ist Wahnsinn!", completion = "Wir nehmen auf, wen wir können, und heilen sie. Auch wenn wir sie dazu festbinden müssen.\n\nIch hoffe ja schwer, dass diese Magie keine anhaltende Wirkung hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[72447] = { id = 72447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die größte Bedrohung", description = "Mächtige Djaradin und andere Kreaturen bedrohen die Obsidianzitadelle und die Sicherheit meines Schwarms.\n\nDas können wir nicht zulassen.\n\nHelft uns, das Gebiet zu sichern. Findet und eliminiert zwei unserer stärksten Feinde.", sourceObjective = "Eliminiert zwei seltene Gegner in der Obsidianzitadelle oder dem Schlackensumpf.", completion = "Gut gemacht. Eure Entschlossenheit zu helfen, blieb nicht unbemerkt... und ist willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72448] = { id = 72448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Vermächtnis sichern", description = "Ich habe nicht so hart gearbeitet und bin so weit gekommen, um die Zitadelle jetzt zu verlieren!\n\nLeider sind neue Bedrohungen aufgetaucht. Kann ich mich auf Eure Unterstützung bei deren Beseitigung verlassen?\n\nHelft, die Gegend zu sichern. Findet zwei unserer mächtigsten Gegner und löscht sie aus.", sourceObjective = "Eliminiert zwei seltene Gegner in der Obsidianzitadelle oder dem Schlackensumpf.", completion = "Gut gemacht! Ich wusste, dass ich mich auf Euch verlassen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[72449] = { id = 72449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg damit!", description = "Wir kommen zu spät, {name}.\n\nClessington hat sich in der Abtei verschanzt und verbreitet den chaotischen Einfluss des Amuletts in ganz Nordhain!\n\nIch glaube, die meisten Leute hier können Freund und Feind nicht mehr unterscheiden.\n\nDieser Kerl scheint mir einer zu sein, der immer einen Plan B hat. Die Agenten müssen doch irgendwie an Clessingtons Barriere vorbeikommen können. Erledigt sie und sucht nach etwas Nützlichem!", sourceObjective = "Sammelt 4 Barrierenschlüssel von leitenden Bediensteten.", progress = "Wir müssen die Barriere überwinden und so schnell wie möglich zu Clessington aufschließen!", completion = "Hmm, die scheinen irgendwie zusammenzupassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[72450] = { id = 72450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clessingtons Testament", description = "Ich bin im Gegensatz zu meinem Vater keine große Magierin, aber ein paar seiner Kniffe kenne ich schon.\n\nIch habe diese Signets gesehen, die Ihr von den Vollstreckern habt. Die Privatgemächer meines Vaters waren mit einem ähnlichen magischen Amulett verschlossen, das man in Einzelteile zerbrechen konnte.\n\nLasst mich diese Signets zu einem arkanen Schlüssel zusammensetzen. Damit sollten wir die Barriere öffnen können.\n\nDann... kann ich nur darauf hoffen, dass er sich zur Vernunft bringen lässt.", sourceObjective = "Stellt Graf Clessington in der Abtei von Nordhain.", progress = "Ich hasse es, dass es so weit kommen musste...", completion = "Entschuldigt, ich brauche einen Moment. Er war kein guter {race}, aber... er war immer noch mein Vater.", sourceObjectiveStatus = "unverified-source-field" }
quests[72451] = { id = 72451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wille zum Überleben", description = "...Es ist also erledigt.\n\nIch hätte dem Mann gern noch weitere Fragen gestellt. Aber die Macht hat ihn überwältigt.\n\nWir dürfen nicht zulassen, dass jemand anderes das Amulett in die Finger bekommt. Nehmt es an Euch, {name}. Dann sorgen wir gemeinsam dafür, dass es wieder nach Sturmwind zurückkommt.", sourceObjective = "Nehmt das Drachenfeueramulett an Euch.", progress = "Sind wir hier fertig?", completion = "Ich bin es leid, {name}. Die ständigen Kämpfe. Ich bin es leid, manipuliert, alleingelassen und verletzt zu werden. Es geht allen unseren Leuten genauso.\n\nIch vermisse die Person, die ich einmal war. Einfach ein Mädchen, das in die Fußstapfen seines Vaters treten und wie er den Leuten in seiner Heimat helfen wollte. Ein Mädchen, das dies für möglich hielt.\n\n\n\n...Ich bin Euch wohl einen Dank schuldig. Ihr habt mir viel zum Nachdenken gegeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[72452] = { id = 72452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geht mit Ehre", description = "Diese Mission hat alle unsere Erwartungen gesprengt. Ihr habt Euch sehr gut geschlagen, {name}. Ich will gar nicht daran denken, was ohne Euch hier passiert wäre.\n\nDer König hatte vor einer Weile eine Rüstung in Auftrag gegeben. Eine Rüstung, die unsere größten Helden zieren sollte.\n\nIhr habt Euch diese Ehre mehr als verdient.\n\nTreffen wir uns im Tal der Helden, {name}.", sourceObjective = "Trefft Euch mit Shaw im Tal der Helden in Sturmwind.", progress = "Ihr hab viel für Sturmwind getan, Held.", completion = "Ihr habt so viel für diese Stadt getan. Habt Dank, Held.\n\nTragt diese Rüstung mit Stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[72453] = { id = 72453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrat der Bruderschaft", description = "Ich hätte es wissen müssen. Ich habe in dem Moment, in dem die Begnadigungen angeboten wurden, die Kontrolle über die Bruderschaft verloren. Wer noch irgendwelchen Prinzipien treu war, ist längst weg.\n\nJetzt sind nur noch die Grobiane übrig. Und Duncon Ratsbon war schon immer der Schlimmste.\n\nVerschwinden wir hier, {name}. Wenn diese Narren versuchen, uns etwas anzuhaben, zeigen wir ihnen, was passiert, wenn man einer van Cleef in die Quere kommt.", sourceObjective = "Entkommt aus dem Versteck der Defias.", completion = "Einerseits habe ich ein seltsames Gefühl... andererseits scheint mir das seit Langem überfällig.\n\nSeit dem Kampf gegen die Legion fühlte ich mich der Bruderschaft immer weniger verbunden. Nach und nach gab es mehr Hilfe für Westfall. Sie wird zwar nie ausreichen, aber... die Flammen der Revolution verloschen allmählich.\n\n...Vielleicht werde ich auch einfach nur alt.\n\nDennoch... Einst hielt ich mich für eine, die sich für das Volk einsetzte. Ich habe zwar Fehler gemacht und ihnen auch Leid beschert... aber wen haben sie denn sonst?\n\nIch muss meine Sache besser machen. Nicht für die Defias, sondern für Westfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[72454] = { id = 72454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Obsidianjungtier", description = "Ein Ei des schwarzen Drachenschwarms steht kurz vor dem Schlüpfen.\n\nMeldet Euch bei Mutter Elion im Rubinlebensschrein, um das Ei abzuholen. Dann bitte ich Euch, das Ei zum Obsidianschwurstein zu bringen, damit es an einem Ort ausschlüpft, an dem die Macht seines Schwarms stark ist.\n\nSobald das getan ist, kehrt mit dem Schlüpfling hierher zurück, wo wir uns weiter um sie kümmern werden.", sourceObjective = "Sammelt das Schwarzdrachenei beim Rubinlebensschrein ein und lasst es beim Obsidianschwurstein schlüpfen.", progress = "Habt Ihr den neuesten Schlüpfling mitgebracht?", completion = "Ein unverdorbenes Obsidianjungtier.\n\n<Ein kleines Lächeln stiehlt sich auf Lasztaks Gesicht.>\n\nEs ist wirklich lange her.", sourceObjectiveStatus = "unverified-source-field" }
quests[72455] = { id = 72455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wärme und Behaglichkeit", description = "Damit sich das Obsidianjungtier wohl fühlt, müssen wir ihr ein ordentliches Nest bauen.\n\nIhr werdet dieses Nest aus Kohle von der Obsidianzitadelle bauen müssen, damit es warm und passend ist. Zweitens wird Archivarin Edress Euch dabei helfen können, etwas zu finden, das sie an ihren Schwarm bindet.\n\nWir werden auch etwas aus der Zaralekhöhle brauchen, da die Geschichte des schwarzen Drachenschwarm eng mit dieser verbunden ist. Jemand in Loamm kann sicher helfen.", sourceObjective = "Sammelt Vorräte für das Nest des Obsidianjungtiers.", progress = "Wir haben am meisten zu lernen, was dieses Obsidianjungtier angeht... Ich hoffe, sie wird Geduld haben, während wir uns verbessern.", completion = "<Agapanthus blickt erleichtert zum Nest des Obsidianjungtiers hinüber.>\n\nSie wird es in ihrem neuen Nest gemütlich haben. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[72456] = { id = 72456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folianten des Vertrauens", description = "Obwohl wir die oberen Ebenen der Obsidianzitadelle sichern konnten, plündern die Streitkräfte der Djaradin weiterhin den Innenhof. Doch dort lagern lauter unbezahlbare historische Aufzeichnungen! Wir müssen schnell handeln, um alles zu retten, das die Abstammung des schwarzen Drachenschwarms dokumentiert.\n\nFurorion und Sabellian brauchen diese Informationen, Ihr könntet Euch also gut bei ihnen einschmeicheln, wenn Ihr jedem einen Folianten mitbringt.\n\nGeht zum eingestürzten Turm der Zitadelle, dort solltet Ihr etwas Wertvolles finden können.", sourceObjective = "Findet Bände der Obsidiangenealogie und bringt sie zu Furorions und Sabellians Rüstmeistern.", progress = "Habt Ihr die Folianten gefunden?", completion = "Ausgezeichnet! Ich bin sicher, Furorion und Sabellian werden mit Euren Anstrengungen zufrieden sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[72457] = { id = 72457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine selbstgekochte Mahlzeit", description = "Schwarze Drachenwelpen müssen groß und stark werden. Unser Schlüpfling hier sieht recht klein aus, also wird sie etwas kräftiges und reichhaltiges brauchen, das ihr hilft.\n\nEntenbraten ist nicht nur gut für die Ausdauer, sondern auch das Gehirn. Ich denke, das wäre die perfekte Mahlzeit für unseren jungen Schlüpfling.", sourceObjective = "Sammelt Bratentenschmaus für die Obsidianwelpin. Ihr könnt dies über Kochkunst selbst herstellen oder im Auktionshaus kaufen.", progress = "Ente ist eine auf den Dracheninseln heimische Spezialität. Wusstet Ihr, dass wir sie nirgendwo sonst in Azeroth gefunden haben?", completion = "Welpen brauchen viel Energie, um zu wachsen. Sie sind unersättlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[72458] = { id = 72458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sowas von nervös", description = "Jeder Welpe muss spielen, um sich auszutoben. Unsere neue Obsidianfreundin ist keine Ausnahme.\n\nDie Schlüpflinge lieben es, Fangen zu spielen. Seht doch mal, ob sie mit Euch spielen will!", sourceObjective = "Spielt mit dem Obsidianjungtier.", completion = "Sie ist recht zaghaft, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[72459] = { id = 72459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probleme mit Enten?", description = "Ich will ehrlich mit Euch sein, {name}.\n\nEs ist so lange her, dass wir mit dem schwarzen Drachenschwarm zu tun hatten, dass ich Euch wenig über ihn sagen kann. Ich weiß, dass sie mächtige Krieger sind, mutige Beschützer von uns allen.\n\nRusziona ist noch jung, aber vielleicht sollten wir sehen, wie sie sich im Kampf schlägt? Nehmt sie mit und lasst sie an Enten auf den Ebenen von Ohn'ahra üben. Mal sehen, was sie kann.", sourceObjective = "Tötet gemeinsam mit Rusziona 5 Blauschnabelwatschler im Urzeitlichen Tal.", completion = "Sie hat was?!\n\n<Agapanthus legt das Gesicht in die Hände und seufzt schwer.>\n\nWisst Ihr was? Das war unbedacht von mir. Ich sollte das besser wissen.\n\nIch glaube, wir müssen ganz von vorn anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72460] = { id = 72460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdverbundenes Haustier", description = "Ich mache mir Sorgen um Ruszi. Sie ist unfassbar nervös und unsicher und sie erschrickt vor allem und jedem! Ich habe noch nie gehört, dass ein schwarzer Drache so viel Angst vor der Welt hat.\n\nIch glaube, der beste Weg, um ihr Vertrauen zu stärken, ist, ihr einen Gefährten zu suchen. Jemand, der stabil und stark ist und sich nicht zu schnell oder plötzlich bewegt.\n\nDer schwarze Drachenschwarm ist für den Schutz der Erde zuständig. Vielleicht passt ein kleiner Elementar gut zu ihr.\n\nSprecht mit Lysindra im Haustierladen in Valdrakken. Sie sollte etwas Passendes haben.", sourceObjective = "Erhaltet ein Haustier für Rusziona.", progress = "Erdelementare sind tolle erste Haustiere. Sie essen Kies, kommen nicht besonders schnell voran und halten fast alles aus!", completion = "Seht Euch nur diesen wunderbaren Elementar an! Hoffentlich kann er dabei helfen, unserer kleinen Welpin mehr Selbstvertrauen zu verleihen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72461] = { id = 72461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anatidaephobia", description = "Es ist so weit, {name}. Iggy, ihr neues Haustier, hat das Selbstvertrauen von Rusziona enorm gestärkt, und ich glaube, sie ist jetzt bereit, sich ihrer größten Angst zu stellen.\n\nEnten.\n\nAn der Küste des Erwachens gibt es eine Tauren, die eine Expertin darin ist, Traumata mithilfe von Haustieren zu heilen. Ich glaube, sie könnte genau das sein, was wir brauchen.\n\nLasztak und Rusziona werden dort auf Euch warten.", sourceObjective = "Helft Rusziona und Iggy, eine Ente in einem Haustierkampf zu besiegen.", progress = "Eine große Ente könnte noch zu viel für Rusziona sein, aber ein Entchen wäre perfekt.", completion = "Danke für alles, was Ihr für Rusziona getan habt, {name}. Sie hat gefragt, ob sie Euch auf einem Eurer Abenteuer begleiten darf. Sie ist sicher, dass sie in Sicherheit ist, solange sie bei Euch ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[72462] = { id = 72462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilung unseres Volks", description = "Es ist seltsam, {name}. Wir haben seit Jahren Frieden, und doch fühle ich mich ruhelos. Ich habe die Horde und meinen Sohn, und doch fühle ich mich einsam. Euch geht es genauso, nicht wahr? Das sehe ich in Euren Augen, wie auch in den Augen vieler anderer Orcs.\n\nIch denke, vielleicht haben wir uns auf Azeroth zurechtgefunden, dabei aber vergessen, wer wir Orcs sind.\n\nKommt mit. Ich möchte diese Sorgen mit einem alten Freund besprechen und hätte Euch dabei gern an meiner Seite.", sourceObjective = "Reist mit Etrigg ins Alteractal, um die Zukunft der Orcs mit Drek'Thar zu besprechen.", completion = "Eigentlich sollte das ein ruhiger Familienbesuch bei Drek'Thar werden. Vielleicht noch ein Gespräch mit Durak über seine Zukunft.\n\nStattdessen haben wir einen Weg eingeschlagen, der sich auf das gesamte Volk der Orcs auswirken wird!\n\nVersteht mich nicht falsch. Ich glaube schon, dass wir die beste Entscheidung getroffen haben. Ich bin nur überrascht, wie schnell das geschehen ist. Ich soll eine Scharfseherin werden...\n\nWir haben viel zu tun und sollten es anpacken.", sourceObjectiveStatus = "unverified-source-field" }
quests[72463] = { id = 72463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galgars Kaktusapfel Surprise...", description = "<Die letzten Worte der jungen Orcfrau äußerten die Bitte, Galgar diese Kaktusäpfel zu bringen.\n\nWerdet Ihr diese Bitte erfüllen?>", sourceObjective = "Bringt den Sack voller Kaktusäpfel zu Galgar.", progress = "Ach, hallo, {name}. Was habt Ihr denn da?", completion = "Warum bringt Ihr die denn? Ich hatte doch...\n\nOh nein.\n\nDafür sollte doch niemand sterben! Ich stelle allen jungen Orcs diese Aufgabe! Die soll doch einfach sein!\n\nAlso... Danke, dass Ihr die für sie hergebracht habt. Hoffentlich habt Ihr Freude an der Belohnung...", sourceObjectiveStatus = "unverified-source-field" }
quests[72464] = { id = 72464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kosh'harg", description = "Das Kosh'harg wird in Klingenhügel abgehalten. Go'el und Etrigg versammeln jetzt gerade die Klans.\n\nWir müssen vorerst Abschied nehmen. Ihr müsst Euch geistig auf das Om'gora vorbereiten, den Ritus der Ehre. Meine Aufgabe ist es, dafür zu sorgen, dass er selbst für Euch eine würdige Herausforderung wird.\n\nIch rufe unsere Windreiter, damit sie meine Familie zum Kosh'harg bringen. Ihr könnt mit ihnen reisen oder dort zu uns stoßen.", sourceObjective = "Reist zum Kosh'harg in Klingenhügel und beginnt das Om'gora, den Ritus der Ehre.", completion = "Euer Om'gora hat begonnen. Mögen die Geister Euch zum Erfolg geleiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[72465] = { id = 72465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen des Landes", description = "Wenn ein junger Orc den Segen des Landes erhalten möchte, muss er lernen, die Geister zu respektieren, die unter uns weilen. Wenn wir nicht in Harmonie mit den Elementen und Lebewesen um uns leben, kann das zur Katastrophe führen.\n\nIch werde die Geister rufen, und sie werden uns dort hinführen, wo Eure Hilfe benötigt wird. Es liegt an Euch, die Euch gestellte Aufgabe zu bewältigen.", sourceObjective = "Sucht den Geist vom Donnergrat, um zu erfahren, wie Ihr den Segen des Landes erhalten könnt.", completion = "Hört mir zu, junger {race}. Ich bin der Geist, der dieses Gebiet schützt, das Euer Volk \"Donnergrat\" nennt.\n\nIn der Schlucht unter uns gedieh einst das Leben. Mit Eurer Hilfe könnte dies wieder geschehen.\n\nHelft mir jetzt, und beide unsere Völker werden davon profitieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[72466] = { id = 72466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geist vom Donnergrat", description = "Das Leben kann nur gedeihen, wenn ein empfindliches Gleichgewicht aufrechterhalten wird. Die Ankunft Eures Volks und der Menschen war nur das erste in einer Reihe von Ereignissen, die das Land letztlich veröden ließen.\n\nEuch persönlich trifft keine Schuld, doch es liegt in Eurer Macht, wiederherzustellen, was einst war.\n\nTaucht in das Wasser unter uns und bergt die im Schlick vergrabenen Samen. Sie sind eine Erinnerung an den uralten Wald, der einst in Harmonie mit meinem Volk wuchs.\n\nDoch nehmt Euch in Acht. Die Elemente hier sind in Aufruhr.", sourceObjective = "Arbeitet mit dem Geist vom Donnergrat zusammen, um das Leben im Gebiet wieder erblühen zu lassen.", progress = "Ihr seid zurück! Ich darf annehmen, dass Ihr dem Geist vom Donnergrat geholfen habt?", completion = "Ihr habt Eure Sache gut gemacht, {name}. Der Wind trägt den Lobgesang der Geister über Euch mit sich.\n\nMit der Zeit wird der Donnergrat zu einer neuen Oase erblühen, was sowohl dem Volk in Orgrimmar als auch den Donnerechsen zugutekommt.\n\nIhr habt Euch den Segen des Landes verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[72467] = { id = 72467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen des Klans", description = "Ein junger Orc, der den Segen des Klans erhalten möchte, muss lernen, dass ein Klan nur so stark ist wie seine Mitglieder. Beweist den lebenden Orcs Eure Stärke, und dass Ihr würdig seid.\n\nDa Ihr nicht in einen Klan hineingeboren wurdet, müsst Ihr zunächst einen Klan auswählen, dessen Champion Ihr sein möchtet. Dann muss der Häuptling des Klans Euch annehmen.\n\nDie Häuptlinge haben sich in der Kaserne versammelt. Schließt Euch einem Klan an und erfüllt die Aufgabe, die Euch gestellt wird.", sourceObjective = "Wählt einen Klan, dessen Champion Ihr während des Om'gora sein wollt.", completion = "Ihr habt Euren Weg gewählt. Seid Ihr bereit, ihn zu beschreiten?", sourceObjectiveStatus = "unverified-source-field" }
quests[72474] = { id = 72474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Mörder auf der Spur", description = "Gor'krosh, die langen Messer, versetzt das Tal der Prüfungen seit Wochen in Angst und Schrecken. Es werden Orcs vermisst, und viele unserer jungen Schüler wurden verletzt.\n\nDie Peons nennen den geheimnisvollen Angreifer \"die langen Messer\", weil die wenigen Leichname, die wir gefunden haben, alle lange, schreckliche Schnittwunden am Rücken hatten. Die Peons sind verängstigt und verweigern die Arbeit!\n\nWir wissen nicht, mit wem oder womit wir es bei Gor'krosh eigentlich zu tun haben, aber es ist in jedem Fall äußerst gefährlich. Bitte findet dieses Monster und setzt diesem Wahnsinn ein Ende!", sourceObjective = "Holt Informationen über Gor'krosh, die langen Messer, von den Bewohnern des Tals der Prüfungen ein.", completion = "Was habt Ihr herausgefunden?\n\n<Ihr erzählt Kaltunk von dem großen Fußabdruck mit drei Zehen, den von Karranisha erwähnten Raptoren, dem Zeugenbericht des Peons und den Leichnamen mit tiefen Schnitten.>\n\nDas... soll also heißen, dass Gor'krosh in Wahrheit ein riesiger, weißer Raptor ist?!", sourceObjectiveStatus = "unverified-source-field" }
quests[72475] = { id = 72475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gor'krosh in die Enge treiben", description = "Wenn Gor'krosh wirklich ein Raptor ist, müsstet Ihr ihn aufspüren können wie jedes andere Tier auch.\n\nSeht einmal, ob Ihr seine Spur finden könnt. Wir wissen, dass er in letzter Zeit hier war. Stellt ihn in seinem Versteck und setzt dem ein für alle Mal ein Ende!\n\nKehrt unbedingt sofort nach Klingenhügel zurück, wenn Ihr Eure Beute getötet habt. Die Scharfseherin muss einen Beweis dafür sehen.\n\nIch danke Euch, {name}. Mögen die Geister Eure Klinge führen. Lok'tar!", sourceObjective = "Jagt und erledigt Gor'krosh und kehrt mit einem Beweis nach Klingenhügel zurück.", progress = "Habt Ihr die Trophäe? Habt Ihr Euer Gesicht mit dem Blut Eurer Beute bemalt? Ihr erhaltet Euren Segen erst, wenn es getan ist.", completion = "<Aggra begutachtet das Blut auf Eurem Gesicht sorgfältig. Sie nickt, offenbar zufrieden mit dem, was sie gesehen hat.>\n\nIhr habt ihn sauber erlegt und die Jungen und Schwachen ehrenhaft verteidigt. Die Geister sind erfreut.\n\nIhr habt Euch den Segen des Klans verdient.\n\n...Ihr könnt Eure Kleidung zurückhaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[72476] = { id = 72476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen der Ahnen", description = "Der Segen der Ahnen soll junge Orcs lehren, dass die Lebenden alles jenen zu verdanken haben, die vor ihnen kamen. Wir müssen die Ahnen ehren, auf ihre Weisheit hören und ihre Erwartungen erfüllen.\n\nEure Aufgabe besteht daraus, eine Opfergabe zusammenzustellen, die zum einen der geehrten Toten würdig ist und zum anderen würdig ist, den Opferstein beim ersten Kosh'harg Azeroths zu schmücken! Wenn Ihr dem nicht Eure gesamte Energie widmet, wird es nicht ausreichen.\n\nKoch Torka wird Euch anleiten. Die Ahnen werden zusehen.", sourceObjective = "Sprecht mit Koch Torka über die Zusammenstellung Eurer Opfergabe.", completion = "Aha, der große Held braucht Hilfe vom Koch Torka, wie?\n\nNa schön, aber die Arbeit müsst Ihr schon selbst erledigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[72477] = { id = 72477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orcische Lebensmittel", description = "Hier steht ein Rezept für das traditionelle Festmahl drin, das die Klans beim Kosh'harg für die Ahnen hinterließen. Ein paar Zutaten werden wir austauschen müssen, weil es sie eben nicht mehr gibt...\n\nAber dadurch wird es noch besser werden! Wir werden dieses traditionelle Gericht nach azerothischer Art zubereiten!\n\nIch werde Euch alle Bestandteile des Rezepts lehren, aber es liegt an Euch, die Zutaten zu sammeln und es tatsächlich zu kochen. Es sind orcische Händler von überall hergekommen, also solltet Ihr alles, was Ihr braucht, hier in Klingenhügel finden.", sourceObjective = "Besorgt Kochzutaten von Händlern in Klingenhügel.", progress = "Haben wir alles auf der Liste gefunden? Torka meinte, es sollte alles in Klingenhügel zu bekommen sein!", completion = "Wir haben alles auf der Liste gefunden!\n\nWas steht als Nächstes an?", sourceObjectiveStatus = "unverified-source-field" }
quests[72478] = { id = 72478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhm und Ehre", description = "Ihr habt das Om'gora erfolgreich abgeschlossen! Glückwunsch, {name}.\n\nNun ist es Zeit, dass wir feiern! Wir haben für alle hier Versammelten ein Festmahl zu Euren Ehren vorbereitet!\n\nGeht und sonnt Euch im Ruhm, den Ihr Euch verdient habt. Amüsiert Euch. Falls sich diese Orcs nicht benehmen können, erinnert sie ruhig daran, warum Ihr auserwählt wurdet, diesen neuen Ritus zuerst zu durchlaufen!", sourceObjective = "Genießt das Festmahl!", completion = "Ja, ich denke, es wird Zeit, diese Feier zu beenden. Man kann es schließlich auch übertreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[72479] = { id = 72479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aka'Magosh", description = "Das Kosh'harg war ein voller Erfolg, und das haben wir zum großen Teil Euch zu verdanken, {name}.\n\nJetzt muss nur noch Aggra die Zeremonie leiten, die das Fest offiziell beendet.\n\nIch würde gern ein paar Worte sagen, bevor die Menge sich wieder zerstreut. Es gibt ein paar Dinge, die schon lange gesagt werden müssen.", sourceObjective = "Seht zu, wie das Kosh'harg offiziell beendet wird.", completion = "Für unser Volk ist ein neues Zeitalter angebrochen, {name}.\n\nIch hätte mir nie ausmalen können, was dabei herausgekommen ist, Euch an meinem törichten Streben zu beteiligen, ein ausgestorbenes Fest wiederzubeleben.\n\nWir haben diese Rüstung extra für Euch anfertigen lassen. Ihr habt sie Euch mehr als verdient.\n\nEin Hoch auf {name}, Champion der Orcs!", sourceObjectiveStatus = "unverified-source-field" }
quests[72481] = { id = 72481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tour an der Küste des Erwachens", description = "Und was macht am meisten Spaß, wenn es ums Drachenreiten geht? Rennen!\n\nMeine bronzenen Kollegen haben überall auf den Dracheninseln Rennstrecken entworfen. Die Landschaften sind einfach so vielseitig und dynamisch, dass sie fast schon darum betteln, bei Höchstgeschwindigkeiten erkundet zu werden.\n\nWarum probiert Ihr es nicht aus, wenn Ihr mal in der Nähe einer unserer Rennstrecken an der Küste des Erwachens seid?", sourceObjective = "Fliegt einmal auf jeder Rennstrecke der Küste des Erwachens.", completion = "Gute gemacht! Ich dachte mir schon, dass Ihr nicht lange brauchen würdet, um den Dreh bei den Drachenrennen rauszubekommen.\n\nUnd das war gerade erst der Anfang. Als nächstes sind die Ebenen von Ohn'ahra dran!", sourceObjectiveStatus = "unverified-source-field" }
quests[72482] = { id = 72482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortgeschrittene Tour an der Küste des Erwachens", description = "Nun, da Ihr die Basisrennen auf den ganzen Dracheninseln geflogen seid und Euer Können unter Beweis gestellt habt, wie wäre es mit einer neuen Herausforderung?\n\nDie fortgeschrittenen Rennkurse ähneln den Standardkursen, die Ihr bereits kennt, aber viele haben angepasste Flugstrecken oder zusätzliche Hindernisse, die Eure Fähigkeiten auf die Probe stellen.\n\nFangen wir doch mit den Strecken an der Küste des Erwachens an!", sourceObjective = "Fliegt jedes Rennen an der Küste des Erwachens.", completion = "Gut gemacht! Diese Hindernisse piksen ganz schön, wenn man sie das erste Mal trifft. Aber Ihr habt nicht aufgegeben und alle Strecken absolviert!\n\nNa dann! Ihr könnt Euch bestimmt denken, was als Nächstes ansteht. Rennen auf den Ebenen von Ohn'ahra!", sourceObjectiveStatus = "unverified-source-field" }
quests[72483] = { id = 72483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tour auf den Ebenen von Ohn'ahra", description = "Ah, die Ebenen von Ohn'ahra. Ausgedehnte, freie Flächen, Windböen, ungetrübte Aussicht... Und noch mehr Rennstrecken!\n\nWie auch schon an der Küste des Erwachens gilt, wenn Ihr jemanden meiner bronzenen Kollegen trefft, dann sprecht ihn doch auf die Rennstrecke an.", sourceObjective = "Fliegt einmal auf jeder Rennstrecke der Ebenen von Ohn'ahra.", completion = "Ausgezeichneter Flug, {name}! Daran, wie Ihr Euren Drachen steuert, sieht man, wie weit Ihr es als Drachenreiter geschafft habt.\n\nUnd diese Geschwindigkeit! Ich bin mir sicher, dass Ihr nun versteht, wie befreiend es ist, wie ein Drache zu fliegen!\n\nNa dann! Es gibt noch mehr Orte zu sehen und Rennen zu bestreiten. Nächster Halt: das Azurblaue Gebirge!", sourceObjectiveStatus = "unverified-source-field" }
quests[72484] = { id = 72484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortgeschrittene Tour auf den Ebenen von Ohn'ahra", description = "Die fortgeschrittenen Strecken sollten etwas herausfordernder sein, aber ich bin mir sicher, dass Ihr auch damit zurechtkommen solltet!\n\nMeine bronzenen Kollegen haben auf den Ebenen von Ohn'ahra fortgeschrittene Strecken mit ein paar Hindernissen und Überraschungen für Euch vorbereitet. Ihr könnt dort auch gegen Eure eigenen Bestzeiten antreten!\n\nViel Glück!", sourceObjective = "Fliegt jedes fortgeschrittene Rennen auf den Ebenen von Ohn'ahra.", completion = "Gut gemacht! Ihr seid wie ein Welpling in der Luft, oder eine Ente auf dem Wasser, wie manche sagen würden.\n\nAls Nächstes stellen wir uns im Azurblauen Gebirge neuen Herausforderungen!", sourceObjectiveStatus = "unverified-source-field" }
quests[72485] = { id = 72485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tour im Azurblauen Gebirge", description = "Rennstrecken im Azurblauen Gebirge sind eine einzigartige Erfahrung. Die hohen Gipfel, das schneebedeckte Terrain und die dichten Wälder bieten zahlreiche interessante Hindernisse... und Herausforderungen!\n\nSucht nach meinen bronzenen Kollegen, wenn Ihr dort seid, und probiert Euch an ihren Strecken!", sourceObjective = "Fliegt einmal auf jeder Rennstrecke im Azurblauen Gebirge.", completion = "Was für eine Darbietung, {name}! Geschickt, wie Ihr die Strecken des Azurblauen Gebirges bewältigt habt...\n\nUnd Ihr habt kaum einen Kratzer davongetragen! Mir kommt es ständig so vor, als würden mir die Bäume plötzlich in die Flugbahn springen...\n\nAls Nächstes geht es nach Thaldraszus... für noch mehr Rennen, natürlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[72486] = { id = 72486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortgeschrittene Tour im Azurblauen Gebirge", description = "Die fortgeschrittenen Strecken im Azurblauen Gebirge sind darauf ausgelegt, Euren Fertigkeiten im Drachenreiten zu neuen Höhen zu verhelfen! \n\nAber... fallt bitte bloß nicht aus eben jenen Höhen!\n\nWenn Ihr bereit seid, sucht meine bronzenen Kollegen auf und fliegt ihre Strecken!", sourceObjective = "Fliegt jedes fortgeschrittene Rennen im Azurblauen Gebirge.", completion = "Gut gemacht! Ihr habt fast alle fortgeschrittenen Rennstrecken der Dracheninseln gemeistert.\n\nNa dann! Auf nach Thaldraszus zu den letzten paar Herausforderungen!", sourceObjectiveStatus = "unverified-source-field" }
quests[72487] = { id = 72487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tour in Thaldraszus", description = "Thaldraszus. Es ist die Heimat des Sitzes der Aspekte und eines Großteils der Geschichte der Drachenheit. \n\nEs ist außerdem die Heimat schwindelerregender Gipfel und steile, tiefe Schluchten, die geradezu zu einem Überflug einladen!\n\nMeine Bronzekollegen haben wie immer Rennstrecken in Thaldraszus aufgebaut, die Ihr fliegen könnt, während Ihr das Land erforscht. \n\nWarum seht Ihr sie Euch nicht an und schließt Eure Tour der Dracheninseln ab?", sourceObjective = "Fliegt einmal auf jeder Rennstrecke in Thaldraszus.", completion = "Fantastisch! Ihr habt jedes Rennen auf den Dracheninseln bestritten. Das ist ein unwiderlegbarer Beweis Eures Könnens als Drachenreiter!\n\nDoch ich sehe noch weitere Herausforderungen und fortgeschrittene Strecken, die Euch in der Zukunft erwarten! \n\nAber für den Moment habt Ihr meine Glückwünsche!", sourceObjectiveStatus = "unverified-source-field" }
quests[72488] = { id = 72488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortgeschrittene Tour in Thaldraszus", description = "Einmal mehr auf nach Thaldraszus mit seinen Gipfeln und Tälern und Rennstrecken, die nur auf Euch warten!\n\nSuch meine bronzenen Kollegen auf, um die fortgeschrittenen Rennen zu fliegen und Eure Tour auf den Dracheninseln zu beenden!", sourceObjective = "Fliegt jedes fortgeschrittene Rennen in Thaldraszus.", completion = "Ihr habt es geschafft! Ihr habt alle fortgeschrittenen Rennstrecken auf den Dracheninseln abgeschlossen. Ich bin absolut zufrieden... und beeindruckt! \n\nIhr könnt die Rennen jederzeit wiederholen, um Eure Bestzeiten zu schlagen. Der Himmel gehört Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[72510] = { id = 72510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbotene Insel 1/1" }
quests[72512] = { id = 72512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine flüsternde Brise", description = "<Godoloto legt den Kopf schräg, nickt Euch zu und sieht Euch schließlich in die Augen. Nach einem langen Moment hebt sie den Blick zum Himmel... und dem Berg neben Maruukai. Ihr spürt, dass sie Euch bittet, zu Ohn'ahras Horst hinaufzureisen.", sourceObjective = "Nähert Euch Ohn'ahra in Ohn'ahras Horst.", progress = "<Ohn'ahra sieht Euch anerkennend an.>", completion = "<Als Ihr Euch nähert, lässt sich der große Ohunageist auf dem Boden nieder und blickt Euch an. Sie senkt den Kopf, um sanft Eure Stirn mit der ihren zu berühren. In diesem Moment breitet sich eine angenehme Wärme in Euch aus. Die Winde sind zum Greifen nah.>", sourceObjectiveStatus = "unverified-source-field" }
quests[72513] = { id = 72513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Schicksal", description = "<Rufer/Ruferin>! Ihr habt möglicherweise vor kurzem eine Störung gespürt.\n\nEbyssian und ich haben begonnen, die uralten Zauber zu zerstören, die den Dracthyr die Essenz des schwarzen Drachenschwarms entzogen. Ich nehme an, voll ausgebildete Rufer wie Ihr sind in der Lage, die Veränderung zu spüren.\n\nAber da ist mehr. Bitte sucht Ebyssian und mich beim Hohen Hort auf der Verbotenen Insel auf. Wir werden eine Drachin befreien.", sourceObjective = "Sprecht mit Schuppenkommandantin Glutthal am Hohen Hort.", completion = "Bereithalten, {class}. Wir haben vielleicht ein Problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[72514] = { id = 72514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hohe Hort", sourceObjective = "Stört 4 Essenzsammler.", completion = "Gut gemacht. Wir werden Ebyssian brauchen, um diesen letzten Strang Magie zu zerschlagen und die Gefangenschaft aufzuheben.", sourceObjectiveStatus = "unverified-source-field" }
quests[72515] = { id = 72515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkung eines Drachen", description = "Adamanthia!\n\nSie war eine Ewigkeit in Agonie gefangen. Während die Dracthyr schliefen, hat sie gelitten.\n\nIch hoffe nur, dass sie während ihrer langen Gefangenschaft nicht dem Wahnsinn von Todesschwinge verfallen ist. Der Zeitenfluss könnte ihren Verstand beeinträchtigt haben.\n\nMacht Euch bereit, Champion. Wenn sie angreift, müsst Ihr Ebyssian unterstützen. Verstärkt seine Fähigkeiten, sodass er Adamanthia bändigen kann, ohne sie zu töten.\n\nSie hat eine Chance verdient. Wir müssen sie ihr gewähren.", sourceObjective = "Helft Ebyssian, Adamanthia zu beruhigen.", progress = "Adamanthia hat lange genug auf diesen Tag gewartet. Hoffen wir, dass er nicht zu spät gekommen ist.", completion = "Es ist... alles in Ordnung.\n\nIch glaube... sie wird sich danach wieder erholen. Danke, {class}. Jetzt können wir Adamanthia die Hilfe und Heilung zukommen lassen, die sie braucht. Wir werden sie in dieser neuen Welt willkommen heißen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72519] = { id = 72519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temporale Zweistimmung", description = "Ich verstehe... Sie fallen durch Möglichkeiten und die Zeit selbst.\n\nBeeilt Euch, ich habe einen weiteren Punkt in der Zeitlinie entdeckt, an dem wir sie auffangen könnten. Er ist... ungewöhnlich, aber lasst Euch nicht von der Fremdartigkeit dieser Welt ablenken. Chronormus Schicksal liegt in Euren Händen.", sourceObjective = "Wendet den Chronokristall auf Eternus und Chromie in Azmerloth an, um zu verhindern, dass sie weiter durch die Zeit fallen.", completion = "Der Prozess war noch nicht abgeschlossen, aber ich kann Chronormu jetzt genauer verfolgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72524] = { id = 72524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basiskletterausrüstung", description = "<Pfadfinder Jeb deutet auf den Versorgungspaket neben sich.>\n\nIhr werdet Vorräte brauchen, um hier draußen zu überleben.\n\nBesorgen wir Euch, was Ihr zum Klettern braucht.", sourceObjective = "Nutzt das Expeditionsversorgungspaket, um Kletterausrüstung zu erforschen.", completion = "Diese Basisausrüstung wird Euch den Anfang erleichtern.\n\nKommt zurück, wenn Ihr mehr Vorräte der Dracheninseln habt, um den Umgang mit besserer Ausrüstung zu lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72525] = { id = 72525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basiskatalogisierungsausrüstung", description = "Jeder Katalogisierer der Expedition braucht eine eigene Kamera!\n\nIhr müsst Eurer keinen besonderen Namen geben, aber ich würde es Euch dennoch raten. So macht es viel mehr Spaß!\n\nPfadfinder Jeb sollte Euch mit allem versorgen können, was Ihr braucht.\n\nIch habe noch nie etwas gebraucht, was er nicht bei sich hatte. Er ist unglaublich!", sourceObjective = "Nutzt das Expeditionsversorgungspaket, um Katalogisierungsausrüstung zu erforschen.", completion = "Oh, Eure neue Kamera ist wundervoll. Sie passt perfekt zu Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[72526] = { id = 72526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rast des Hüters", description = "Ich sehe nur ungern, wie andere von Tyr Geschmiedete außer Gefecht gesetzt werden. Sie haben sich solche Mühe gegeben, das Grabmal vor dem Einsturz zu bewahren, und nun wird es ohne den geringsten Rest von Tyrs Licht vor sich hinvegetieren.\n\n<Koranos deutet auf die Silberschuppe.>\n\nIch hoffe, was auch immer in der Schuppe steckt, rechtfertigt ihre Zerstörung. Lasst uns nach einer weiteren Schalttafel suchen, um herauszufinden, was die Schuppe aufgenommen hat, falls sie überhaupt etwas beinhaltet.", sourceObjective = "Entkommt zum Finstermarsch.", progress = "Wir handeln im Dienste Tyrs. Er hätte Verständnis dafür.", completion = "Wir sind vorerst in Sicherheit, aber wir sollten uns nicht zu viel Zeit lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72527] = { id = 72527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pechsträhnen gibt es nicht", description = "Ihr könnt mir glauben oder nicht, ich wäre längst auf den Inseln, wenn ich nicht noch etwas zu erledigen hätte. Ich hatte in letzter Zeit nicht viel Glück. Ich habe Schulden beim Baron und die hat niemand lang. Er wird mich finden und häuten, wenn ich nicht bezahle.\n\nIch habe sein Geld in diese magischen Kristalle gesteckt, aber deren Marktpreis ist dank dem Reißer auf der Titelseite des Beutebucht-Anzeigers gerade in den Keller gefallen. Außerdem warte ich immer noch auf die Lieferung der Kristalle!\n\nIrgendjemand muss es auf mich abgesehen haben. Vielleicht können mir die Gutstichs helfen.", sourceObjective = "Findet Blixrez Gutstich bei Gerberei und Lederarbeiten in Beutebucht.", completion = "Es ist kein Wunder, dass mir niemand umsonst helfen will. Fragt Blixrez nach seinem Preis.", sourceObjectiveStatus = "unverified-source-field" }
quests[72528] = { id = 72528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belebungskatalysator", description = "Der Katalysator ist ein mächtiges Artefakt, das zu großartigen Taten der Ermächtigung fähig ist. \n\nWenn Ihr an der Seite Eurer Verbündeten den Kampf gegen die größeren Bedrohungen dieses Landes aufnehmt, bringt alles her, was Ihr an Belebung findet. Damit könnt Ihr den Katalysator antreiben und Eure Ausrüstung mit der Weisheit und Macht von Tyr persönlich erfüllen.", sourceObjective = "Sammelt Belebung von Gruppenereignissen auf den Dracheninseln.", completion = "Ah! Eine wunderbare Sammlung von Ideen und Konzepten. So viel hat sich geändert und so vieles nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[72529] = { id = 72529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen ist alles", description = "Informationen sind nicht billig. Zeros sollte das von allen am besten wissen.\n\nDie Leute haben gefährliche Krokilisken rund um die Janeirospitze gesichtet. Wisst Ihr, was ich da sehe? Geld, Geld, Geld! Holt mir ihre kostbaren Häute, dann fallen mir vielleicht ein paar wichtige Details zu den Kristallen wieder ein, hinter denen Zeros her ist.\n\nWenn Euch das zu gefährlich ist, akzeptiere ich vielleicht auch andere Zahlungsarten. Ihr wisst schon, die gebräuchlichste von allen.\n\n<Blixrez verschränkt erwartungsvoll die Arme.>", sourceObjective = "Sammelt 3 Krokiliskenhäute an der Janeirospitze oder bezahlt Blixrez Gutstich in Gold.", progress = "Freundschaft ist wie eine Waage. Sie muss um jeden Preis im Gleichgewicht bleiben.", completion = "Mhmm, das wird ausreichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[72530] = { id = 72530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dann eben Bestechung", description = "Der Halunke! Ich hatte eine Abmachung mit Arty, die Kristalle in der Zeitung zu vermarkten. Jemand muss ihm ein besseres Angebot gemacht haben.\n\nArty inspiziert regelmäßig den Uferbereich, an dem die Venture Company arbeitet. Er hat immer seine eigenen Wachen dabei, aber in Beutebucht ist niemand immun gegen Gold.\n\nNehmt mein letztes bisschen Gold. Geht zu den Ölplattformen und bestecht die Wachen, damit sie beide Augen zudrücken, wenn Ihr Euch Arty vornehmt.", sourceObjective = "Benutzt das Gold, um Artys angeheuerte Leibwachen zu bestechen, und stellt Feldmesser Arty dann an den Wilden Ufern.", progress = "Das war mein ganzes Gold, wenn Ihr also den Rest mit ein paar gut platzierten Schlägen begleichen möchtet, sage ich nicht nein.", completion = "Piraten?! Aber natürlich. Jetzt wissen wir, wo wir als Nächstes hin müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72532] = { id = 72532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geld regiert die Welt!", description = "Grub Rotschnitt und seine Mannschaft sind berüchtigt für ihre Geldgier. Sie tun alles dafür.\n\nIch nehme an, dass es auf diesem Schiff einen Schatz zu holen gibt. Aber falls dem nicht so ist, müssen sie trotzdem Gold in den Taschen haben. Tut Ihr mir den schmutzigen Gefallen, es einzutreiben?\n\nWie Ihr mit ihnen verhandelt, ist mir egal, solange Ihr sie nicht tötet! Ich habe nicht vor, heute eine Blutfehde anzuzetteln.", sourceObjective = "Sammelt 1500 Goldmünzen von Grub Rotschnitts Piraten an der Südlichen Ungezähmten Küste.", progress = "Es wird höchste Zeit, dass diese Piraten lernen, dass sie nicht jedem auf der Nase herumtanzen können.", completion = "Oh mein Gold, das sieht nach einer stattlichen Summe aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[72533] = { id = 72533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristalle hin oder her", description = "Grub. Rotschnitt. <Zeros spuckt aus.> Ein verbitterter, alter Verlierer, der sich für besonders hart hält, weil er groß und breit ist. Es macht ihn wahnsinnig, dass einer wie ich mehr Geld verdient als er.\n\nOb Ihr es glaubt oder nicht, was ich im Auktionshaus treibe, ist fair. Im Vergleich zu ihm bin ich ein Heiliger!\n\nGrub hat also meine Kristalle verkauft, was? Und dann hat er Arty bezahlt, damit er lügt, weil so niemand nach ihnen suchen würde. Ein sauberer Plan.\n\nGrub muss irgendetwas Wertvolles auf seinem Schiff haben. Tja, das holen wir uns. Durchsucht das Schiff gründlich.", sourceObjective = "Beschafft Grub Rotschnitts Schatz von seinem Schiff an der Südlichen Ungezähmten Küste.", progress = "Bitte beeilt Euch! Der Baron hat das mit meinen Schuppen todernst gemeint. Wie Ihr wisst, bin ich ein Drache, und meine Schuppen sind eine ganze Menge wert.", completion = "Was habt Ihr ergattert?", sourceObjectiveStatus = "unverified-source-field" }
quests[72534] = { id = 72534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quitt mit dem Baron", description = "Ha...! Ihr seid gerade rechtzeitig zurückgekommen. Eine Minute später hättet Ihr vielleicht einen gehäuteten Drachen vorgefunden.\n\nGebt ihm schnell den Schatz.", sourceObjective = "Überbringt den Schatz Baron Revilgaz.", progress = "Nun, gebt ihm endlich das Gold, ja? Bitte!", completion = "Senegos! Ihr habt mir gerade das Leben gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[72535] = { id = 72535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonflight (61-69) E" }
