quests[72545] = { id = 72545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hort der Gefallenen", sourceObjective = "Findet das Hornsignet von Tetsos, das Hornsignet von Arrosh, das Hornsignet von Ekrati und das Hornsignet von Hermin im Verlorenen Athenäum.", progress = "Hmm? Entschuldigt, ich bin in Gedanken gerade... woanders.", completion = "<Glutthal nickt Euch ernst zu.>\n\nVielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[72546] = { id = 72546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akademische Unterstützung", description = "{name}! Mir ist bei dem Dialekt der Winterpelze ein Durchbruch gelungen. Ihr habt den Ball ins Rollen gebracht, also dachte ich, ich sollte Euch auf dem Laufenden halten.\n\nTrefft mich in Therons Wacht und ich werde Euch alles darüber erzählen.", sourceObjective = "Trefft Sonova Schneeweh in Therons Wacht.\n\nBereitgestellter Gegenstand:", completion = "Schön Euch wiederzusehen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[72547] = { id = 72547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akademische Beschaffungen", description = "Ich geh zu dem Dorf und überbringe ihnen die schlechten Nachrichten... oder versuche es. Der Winterpelzdialekt ist schwierig zu erlernen.\n\nIhr müsst für mich losziehen und ein paar Furbolgschriftstücke als Proben sammeln, damit ich was zum Studieren hab, wenn wir weiter darauf hoffen wollen, dass wir uns irgendwann mal richtig verständigen können.\n\nDie Primalisten haben die verbleibenden Furbolgs des Gebirges entweder ausgelöscht oder konvertiert, also versucht, ihnen irgendwie ein paar ihrer kulturellen Artefakte abzuknöpfen.\n\nIch brauche für den Anfang mindestens fünf, aber holt mir so viele wie möglich, und ich bringe Euch weiter bei, was ich lerne.", sourceObjective = "Bergt Artefakte der Furbolg von Primalisten im Azurblauen Gebirge.", progress = "Was habt Ihr da für mich?", completion = "Nicht übel für den Anfang, {name}.\n\nAber falls wir uns jemals richtig verständigen wollen, werde ich eine ganze Menge mehr brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[72548] = { id = 72548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonflight (61-69) E" }
