quests[72550] = { id = 72550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenschwarm (60 – 69) E" }
quests[72551] = { id = 72551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine lebende Geschichte", description = "Die Winterpelze haben endlich genug Vertrauen in uns, um uns um Hilfe zu bitten.\n\nWir müssen dieses Vertrauen weiter vertiefen, damit wir eines Tages ihre Pfoten in Freundschaft ergreifen können!\n\nDiese Winterpelz, Jyrra, von den, äh, Flauschefuß, sagt, ihre Ältesten haben sich während des Angriffs der Primalisten auf das Dorf in ein Versteck begeben. Ich verstehe ihre Sprache noch nicht, aber es hat den Anschein, als ob die Ältesten Markierungen hinterlassen haben, damit ihr Klan sie später finden kann.\n\nEs ist Zeit, die Winterpelzältesten wissen zu lassen, dass sie sicher wieder nach Hause zurückkehren können. Könnt Ihr die Nachricht überbringen? Es scheint eine recht einfache Aufgabe zu sein.", sourceObjective = "Folgt den Hinweisen, um die versteckten Winterpelzältesten aufzuspüren.", completion = "Moment... ist das wahr? Ihr kommt |A:furblan-d-25:0:1.00|a|A:furblan-d-11:0:1.00|a|A:furblan-d-21:0:1.00|a |A:furblan-d-27:0:1.00|a|A:furblan-d-27:0:1.00|a|A:furblan-d-6:0:1.00|a|A:furblan-d-6:0:1.00|a|A:furblan-d-5:0:1.00|a|A:furblan-d-34:0:1.00|a|A:furblan-d-27:0:1.00|a Dorf?\n\n|A:furblan-d-8:0:1.00|a|A:furblan-d-28:0:1.00|a|A:furblan-d-6:0:1.00|a|A:furblan-d-10:0:1.00|a die Kämpfe vorüber?", sourceObjectiveStatus = "unverified-source-field" }
quests[72552] = { id = 72552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusammen sammeln", description = "Ich habe noch nie einen Fremdling unsere Sprache sprechen hören. Eure Ausdrucksweise ist etwas einfach...\n\nAber nur <ein Freund/eine Freundin> unseres Klans würde sie überhaupt sprechen!\n\nIch bin Ältester Mhaz. Wenn es sicher ist, nach Hause zurückzukehren, sollten wir bald aufbrechen. Aber viele von uns sind schwach vor Trauer in ihren Herzen... und Grummeln in ihren Mägen. Ich würde Euch nicht in Gefahr bringen, und nach Frischfleisch fragen, aber könntet Ihr Wurzeln für uns sammeln? \n\nWir haben schon die in der Nähe eingesammelt. Ich hoffe, dieses Essen für die Seele wird uns genug aufheitern, dass wir wieder zurückkehren können!", sourceObjective = "Sammelt 8 Wurzeln für den Ältesten Mhaz.", progress = "Die Wurzeln wachsen um die Stämme der großen Bäume. Wir |A:furblan-d-29:0:1.00|a|A:furblan-d-10:0:1.00|a|A:furblan-d-25:0:1.00|a|A:furblan-d-27:0:1.00|a|A:furblan-d-20:0:1.00|a |A:furblan-d-14:0:1.00|a|A:furblan-d-10:0:1.00|a|A:furblan-d-5:0:1.00|a |A:furblan-d-10:0:1.00|a|A:furblan-d-7:0:1.00|a|A:furblan-d-20:0:1.00|a|A:furblan-d-34:0:1.00|a nicht in den |A:furblan-d-6:0:1.00|a|A:furblan-d-32:0:1.00|a|A:furblan-d-4:0:1.00|a|A:furblan-d-7:0:1.00|a|A:furblan-d-36:0:1.00|a gewagt, da es |A:furblan-d-27:0:1.00|a|A:furblan-d-30:0:1.00|a|A:furblan-d-16:0:1.00|a|A:furblan-d-25:0:1.00|a so viele Würmer gibt. |A:furblan-d-23:0:1.00|a|A:furblan-d-13:0:1.00|a|A:furblan-d-7:0:1.00|a|A:furblan-d-31:0:1.00|a|A:furblan-d-12:0:1.00|a|A:furblan-d-17:0:1.00|a|A:furblan-d-7:0:1.00|a|A:furblan-d-10:0:1.00|a|A:furblan-d-15:0:1.00|a|A:furblan-d-25:0:1.00|a gibt es |A:furblan-d-27:0:1.00|a|A:furblan-d-30:0:1.00|a|A:furblan-d-16:0:1.00|a|A:furblan-d-25:0:1.00|a |A:furblan-d-10:0:1.00|a|A:furblan-d-7:0:1.00|a|A:furblan-d-20:0:1.00|a|A:furblan-d-34:0:1.00|a mehr?", completion = "Ich bin |A:furblan-d-26:0:1.00|a|A:furblan-d-11:0:1.00|a|A:furblan-d-16:0:1.00|a|A:furblan-d-19:0:1.00|a|A:furblan-d-13:0:1.00|a dass |A:furblan-d-5:0:1.00|a|A:furblan-d-21:0:1.00|a|A:furblan-d-31:0:1.00|a sicher zurückgekehrt seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[72553] = { id = 72553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Größere Anstrengung, größere Belohnung", description = "Wir sind nicht traurig. Wir verhungern. Das ist die Wahrheit. Ein paar leckere Wurzeln werden nicht ausreichen.\n\nÄltester Mhaz nimmt Stärke nicht wahr, aber ich schon. Es sollte (100)-eine Kleinigkeit für Euch sein, uns Frischfleisch zu bringen! Die Würmer im Osten sollten leichte Beute sein.\n\nBitte, kehrt mit so viel zu uns zurück, wie Ihr tragen könnt.", sourceObjective = "Sammelt 12 Stücke Wurmfleisch.", progress = "Wurmfleisch sollte einfach genug sein. Versucht es mit den kleinen Würmern, wenn Ihr die großen nicht schafft.", completion = "Ich wusste, dass ich Euch richtig eingeschätzt hatte, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[72554] = { id = 72554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brecht ihn", description = "Ihr habt diese kleinen Würmer mit einer solchen Leichtigkeit erledigt!\n\nJedoch... Saza ist nicht zurückgekommen. Der Riesenwurm, Eisbrecher, hat uns seit Wochen gejagt. Er hat zwei unserer Ältesten erwischt, während wir Nahrung gesammelt haben, und mich verletzt, als ich versucht habe, sie zu rächen. Und nun, da Saza vermisst wird, befürchte ich das Schlimmste.\n\nFindet Saza und erledigt diesen Wurm!", sourceObjective = "Findet Saza und tötet den Riesenwurm Eisbrecher.", completion = "So. Es war Eisbrecher?\n\n<Matrone Fherg stößt ein trauerndes Heulen aus.>\n\nUnsere schlaue, |A:furblan-d-13:0:1.00|a|A:furblan-d-25:0:1.00|a|A:furblan-d-11:0:1.00|a|A:furblan-d-7:0:1.00|a|A:furblan-d-25:0:1.00|a|A:furblan-d-22:0:1.00|a Welpin... Oh, Saza...\n\nEin jeder von uns würde voller Freude sein Leben für Sazas eintauschen. Eisbrechers |A:furblan-d-25:0:1.00|a|A:furblan-d-8:0:1.00|a|A:furblan-d-20:0:1.00|a |A:furblan-d-23:0:1.00|a|A:furblan-d-2:0:1.00|a|A:furblan-d-14:0:1.00|a|A:furblan-d-7:0:1.00|a|A:furblan-d-10:0:1.00|a|A:furblan-d-34:0:1.00|a |A:furblan-d-14:0:1.00|a|A:furblan-d-10:0:1.00|a|A:furblan-d-5:0:1.00|a |A:furblan-d-26:0:1.00|a|A:furblan-d-4:0:1.00|a|A:furblan-d-10:0:1.00|a wenig |A:furblan-d-5:0:1.00|a|A:furblan-d-9:0:1.00|a|A:furblan-d-14:0:1.00|a|A:furblan-d-18:0:1.00|a|A:furblan-d-35:0:1.00|a, aber das wird sie nicht zurückbringen.\n\nSazas Verlust wird uns alle treffen.", sourceObjectiveStatus = "unverified-source-field" }
