quests[72557] = { id = 72557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonflight (70) E" }
quests[72558] = { id = 72558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere geehrten Ahnen", description = "Es ist an der Zeit, im Verständnis der Winterpelze den nächsten Schritt zu gehen. Dieser Schritt ist ein spiritueller.\n\nSie ersuchen ihre Ahnen um Rat, wenn sie ihren weiteren Weg auswählen. Wir können ebenfalls von ihnen lernen.\n\nAber der Ritus der Winterpelze, ihre Ahnen zu rufen, ist... kompliziert. Und dauert lange.\n\nEs wäre ohnehin beleidigend, ihr Ritual nachzuahmen. Wir machen es auf unsere Art mit Räucherwerk der Rostkiefergeistsprecher.\n\nKommt! Lasst uns die Weisheit ihrer Ahnen offenbaren und mehr über unsere neuen Freunde erfahren!", sourceObjective = "Benutzt Radzas Räucherwerk, um Geistersicht zu ermöglichen.", progress = "Wenn Ihr so weit seid, wird Euch das Räucherwerk ermöglichen, die Geister zu sehen.", completion = "Könnt Ihr sie sehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[72559] = { id = 72559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschichtenjäger", description = "Als die Primalisten unser Dorf überfallen haben, haben sie mehr als nur unsere Leben genommen, sie haben das Herz unserer Gemeinschaft geraubt... unsere unbezahlbaren historischen Dokumente!\n\nIch werde nicht zulassen, dass die Aufzeichnungen unserer Traditionen, Rituale und reichen Geschichte von uns genommen werden! Es gibt noch viel, was wir aus ihnen lernen können.\n\nBitte, holt sie von diesen plündernden Primalistenspähern zurück, damit wir sie erhalten können!", sourceObjective = "Findet die gestohlenen \"Dokumente\" der Winterpelze.", progress = "Haben die Ahnen Euch auf eine Mission entsandt?", completion = "Diese Dokumente sind unglaublich! Was für ein schrecklicher Verlust das für die Winterpelze gewesen wäre.", sourceObjectiveStatus = "unverified-source-field" }
