quests[72584] = { id = 72584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das eigene Netz auswerfen", description = "Wollt Ihr Euer Netz ausprobieren? Geht an die Flussmündung südlich der Küste des Erwachens und sucht einen Ort, an dem es viele Fische gibt. Das sollte ein guter Ort sein, um das Netz auszuwerfen.", sourceObjective = "Werft Euer Fischernetz am Angelloch der Flussmündung aus.", completion = "Gut. Vergesst nicht, Euer Fischernetz in einigen Stunden abzuholen. Wir wollen doch nicht, dass die Fische verkommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[72585] = { id = 72585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freie Orientierung", description = "Ihr habt viel für die Dracheninseln getan, <Held/Heldin>.\n\nViele sind Euch dankbar für Euren Beitrag und wollen Euch vollständig in ihrer Gemeinschaft willkommen heißen. Geht zu ihnen und lernt jede Gruppe und deren Spezialitäten kennen.\n\nGanz wie Ihr den Dracheninseln vieles zu bieten habt, haben viele von uns so einiges, was sie Euch gerne als Gegenleistung anbieten möchten.", sourceObjective = "Schließt die Orientierungsquests in jedem größeren Fraktionshauptquartier ab: Drachenschuppenbasislager, Maruukai, Iskaara und Valdrakken.", completion = "Ihr habt alle getroffen? Ausgezeichnet. Vielleicht schicken sie mir dann endlich keine Botschafter mehr. \n\nIch hoffe, dass Ihr weiterhin die Bindungen stärkt, die Ihr mit diesen Gemeinschaften eingegangen seid. Ihr könnt euch nur gegenseitig helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72586] = { id = 72586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusätzliche akademische Beschaffungen", description = "Macht weiter so!\n\nJe mehr Beispiele der Furbolgsprache ich miteinander vergleichen kann, umso besser werden die Ergebnisse.", sourceObjective = "Bergt Artefakte der Furbolg von Primalisten im Azurblauen Gebirge.", progress = "Hört jetzt nicht auf, wir haben uns selbst eine Sprache beizubringen!", completion = "Ich kümmere mich sofort darum, diesen Stapel zu katalogisieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[72587] = { id = 72587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unglaubliche akademische Beschaffungen", description = "Wo habt Ihr dieses Prachtexemplar her?\n\nDie Primalisten scheinen viel mehr daran interessiert, Zivilisationen zu zerstören, als deren Geschichte zu bewahren, was einen Fund wie diesen umso wertvoller macht.\n\nFür das hier werde ich meinen besten Radierer nehmen!", sourceObjective = "Bergt einen unversehrten Schreiberstock von Primalisten im Azurblauen Gebirge.", progress = "Ich kann es kaum erwarten, mich wieder an die Arbeit zu machen!", completion = "Für einen guten Start in den Tag gibt es nichts Besseres als ein neues Artefakt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72588] = { id = 72588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plünderer der Primalisten", description = "Ich beginne die Grundlagen der Sprache der Winterpelze zu verstehen, aber was ich daraus lerne, ist düster.\n\nSo wie es aussieht, ist eine Gruppe von Winterpelzfuttersammlern auf Primalisten in der Nähe gestoßen. Die Winter hier sind so rau wie alle anderen in Dun Morogh und die Vorräte, die sie gesammelt haben, werden schmerzlich vermisst werden.\n\nWarum versucht Ihr nicht, so viele davon zu bergen, wie Ihr könnt? Mit allen Mitteln, wenn es Euch nichts ausmacht.", sourceObjective = "Erobert Vorräte von den Primalisten zurück.", progress = "Ein ganzes Dorf hängt von diesen Vorräten ab, also seid nicht knausrig, mit dem was Ihr mitbringt.", completion = "Vielleicht werden diese diebischen Primalisten das nächste Mal ihre Pfoten bei sich behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[72589] = { id = 72589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehret ihr Opfer", description = "Wir können nichts mehr für die Futtersammler tun, die von den Primalisten getötet wurden, aber wir können zumindest versuchen, ihren Angehörigen zu helfen, irgendwie damit abzuschließen.\n\nSeht zu, ob Ihr von den Gefallenen ein paar persönliche Gegenstände bergen könnt. Ich bin mir sicher, die Winterpelze werden schätzen, was immer Ihr ihnen bringt.", sourceObjective = "Bergt persönliche Gegenstände von den gefallenen Winterpelzfuttersammlern.", progress = "Wie viele haben die Primalisten getötet?", completion = "Es ist nicht viel, aber immerhin etwas. Und darauf kommt es an.", sourceObjectiveStatus = "unverified-source-field" }
quests[72590] = { id = 72590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursols Weisheit", description = "Wir sind vom Weg des weisen Ursols abgewichen und haben Fokus gegen Besessenheit und Besonnenheit gegen Furcht eingetauscht.\n\nSammelt Zapfen von den mächtigen Rostkiefern. So wie ihre Wurzeln tief in die Erde reichen, sie Kraft aus Wasser ziehen, in die Lüfte hinaufreichen und durch Feuer gereift werden, werden sie ein Symbol unserer erneuerten Hingabe zu wahrer Ausgewogenheit sein.\n\nSchwingt Euch mit Eurem Drachen in die Lüfte und es sollte Euch möglich sein, ausreichend zu sammeln. Die oberen Äste sind der beste Ort, um welche zu finden.\n\nBietet sie Ursol an seinem Schrein in der Nähe an.", sourceObjective = "Erhaltet Ursols Segen.", progress = "Das Gleichgewicht muss wiederhergestellt werden.", completion = "Unser Weg nach vorne ist nun frei. Habt Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[72591] = { id = 72591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Schuld, die beglichen werden muss", description = "{name}, wie ich höre, habt Ihr ein gutes Verhältnis zu den Zentauren der Ebenen von Ohn'ahra aufgebaut. Ich möchte Euch um einen Gefallen bitten.\n\nBaine ist vor ein paar Tagen zu den Ebenen aufgebrochen, um eine Gruppe vermisster Tauren zu suchen. Ich bot an, ihn zu begleiten, aber er bestand darauf, allein zu gehen.\n\nDie Tauren von Donnerfels verbindet eine lange und blutige Geschichte mit den Zentauren von Kalimdor, und das gilt auch für Baine. Die Zentauren der Maruuk sind zwar nicht mit ihnen verwandt, aber ich mache mir dennoch Sorgen.\n\nEure Anwesenheit könnte dazu beitragen, die Spannungen zu verringern. Hoffe ich.", sourceObjective = "Findet Baine auf den Ebenen von Ohn'ahra.", completion = "Ah, {name}. Hat Mayla Euch geschickt? \n\nIch würde das zwar lieber alleine tun, aber ich muss zugeben, dass Eure Bekanntschaft mit den Zentauren nützlich sein könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[72592] = { id = 72592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narben der Vergangenheit", description = "Ein Taurenstamm kam auf die Dracheninseln, angeführt von einem guten Freund, Bovan Windtotem. Niemand hat von ihnen gehört, seit sie diese Ebenen betreten haben.\n\nSollten sie sich verirrt haben, muss ich sie finden. Allerdings habe ich leider die Größe dieses Ortes unterschätzt.\n\nIhr habt eine Verbindung zu den Zentauren aufgebaut. Könntet Ihr mit ihnen sprechen und herausfinden, ob sie irgendwelche Informationen zu Bovan oder seinem Stamm besitzen?\n\nHoffentlich können sie dabei helfen, meine Suche einzuschränken.", sourceObjective = "Befragt die Zentauren der Maruuk zum Verschwinden von Bovan Windtotem.", progress = "Habt Dank für Eure Hilfe. Es wäre mir... unangenehm, direkt mit den Zentauren zu verhandeln.", completion = "Ich habe Euch losgeschickt, um Informationen zu sammeln, nicht um eine von ihnen zu uns einzuladen! Könnt Ihr sie nicht einfach nach Hause schicken?!", sourceObjectiveStatus = "unverified-source-field" }
quests[72593] = { id = 72593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Tomul-tartiger Anfang", description = "Seit die Drachen zurückgekehrt sind, sehen wir eine überwältigende Anzahl Außenseiter durch die Ebenen ziehen. Normalerweise behalten wir unsere Grenzen genau im Auge, aber ihre schiere Zahl zusammen mit der Bedrohung der Nokhud macht es schwierig, ihnen auf der Spur zu bleiben.\n\nEin Späher hat von einer Gruppe von Außenseitern auf der östlichen Straße berichtet, die zu Eurer Beschreibung passt. Wir sollten unsere Suche dort beginnen.\n\nWas Euren Freund angeht: Meine Khan gab mir einen Befehl, und ein eingeschnappter Begleiter wird mich nicht davon abhalten, ihn auszuführen.", sourceObjective = "Trefft Tomul und Baine auf der östlichen Straße in der Nähe des Wasserlochs.", completion = "Wie es scheint, sind die Zentauren hier nicht viel anders als die in Kalimdor.\n\n<Baine betrachtet Tomul misstrauisch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[72594] = { id = 72594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechte Nachrichten überbringen", description = "Sobald wir hier ankamen, wurde Baine fortgerissen. Bovan wird weiter vermisst, also spricht er mit jemandem namens Tagar.\n\nIch wurde natürlich hier draußen sitzen gelassen. Offenbar vertrauen sie mir immer noch nicht.\n\nJedenfalls solltet Ihr hineingehen und mit den Tauren sprechen. Nehmt die Gegenstände, die Ihr gefunden habt, und versucht herauszufinden, wem sie gehört haben. Zumindest könnt Ihr die Familien wissen lassen, was wir bisher entdeckt haben.\n\nAber... seid umsichtig, {name}. Für einige von ihnen könnte dies der schlimmste Tag ihres Lebens sein.", sourceObjective = "Sprecht mit den Tauren und findet heraus, wem die Gegenstände gehörten, die Ihr gefunden habt.", progress = "Tagar kennt mich seit meiner Kindheit. Er war viele Jahre lang der Stellvertreter meines Vaters.\n\nVor langer Zeit war er es, der Rexxar, Rokhan und Chen Sturmbräu auf eine Mission schickte, die mich vor den Zentauren retten sollte.\n\nAber sie brauchten Hilfe, um die Mission abzuschließen... und da trafen sie Bovan Windtotem.", completion = "Danke für das, was Ihr für diese Leute getan habt.\n\nIch gebe es nicht gern zu, aber Tomul scheint ihren Wert unter Beweis zu stellen.\n\nTrotz ihrer unausstehlichen Persönlichkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[72595] = { id = 72595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Bovan Windtotem", description = "Diesem Überlebenden zufolge haben die Zentauren sie völlig überrascht. Bovan führte viele der Krieger gegen die Zentauren an, in der Hoffnung, den anderen genug Zeit zur Flucht zu verschaffen.\n\nEr war erfolgreich, aber Bovan und die meisten der Krieger sind nicht zurückgekehrt. Wir müssen ihn finden, {name}.\n\nIhr müsst für mich die Umgebung absuchen. Wenn Ihr Überlebende findet, schickt sie hierher.\n\nWenn Ihr gefallene Tauren findet... bringt etwas von ihnen mit, das wir ihren Familien geben können.", sourceObjective = "Sucht die Umgebung nach den vermissten Tauren ab.", progress = "Was habt Ihr entdeckt?", completion = "Ich habe mit den Überlebenden gesprochen, und niemand hat Bovan seit der Schlacht gesehen.\n\nDieser Kopfputz, den Ihr bei dem toten Tauren gefunden habt, gehört nicht ihm, also wird er entweder noch vermisst... oder er wurde gefangen genommen.\n\n<Baines Gesichtsausdruck verhärtet sich.>", sourceObjectiveStatus = "unverified-source-field" }
quests[72597] = { id = 72597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursocs Stärke", description = "Es ist viele Jahre her, seit wir dem mächtigen Ursoc zuletzt Opfergaben gebracht haben, aber wir brauchen seinen Segen, wenn wir das Gleichgewicht in unserem Volk wiederherstellen möchten.\n\nSein Schrein ist in den Bergen im Osten verborgen, wo nur wenige zufällig darauf stoßen würden.", sourceObjective = "Erhaltet Ursocs Segen.", completion = "Danke, Fremdling. Auch wenn Ihr düstere Neuigkeiten mit Euch bringt, werden wir Ursocs Vermächtnis so gut ehren, wie es uns möglich ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[72598] = { id = 72598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worte der Winterpelze", description = "Der Winterpelzanführer hat nach Euch gefragt, während Ihr weg wart. Er möchte nochmal mit Euch sprechen.\n\nUnd dank der von Euch geleisteten Arbeit, konnten wir sogar seine Nachricht verstehen!\n\nWir stehen kurz vor einem großartigen Durchbruch, {name}. Stellt Euch nur vor... die Handelswege, die wir errichten könnten! Der kulturelle Austausch, der stattfinden könnte! Die Abhandlungen, die ich veröffentlichen könnte!\n\nNun, warum steht Ihr hier noch herum? Geht und seht nach, was er möchte!", sourceObjective = "Sprecht mit Kranac Weisenschnee.", completion = "Es ist... seltsam, mit einem Fremdling über unsere Traditionen zu sprechen. Aber wenn die Ahnen durch Euch gesprochen haben...\n\nIch habe eine Aufgabe für Euch, {name}. Eine, von der ich mir erhoffe, dass sie uns auf den rechten Weg zurückführt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72599] = { id = 72599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsame Rettungsmission", description = "Tomul sagt, die Angriffe auf die Windtotems wurden von einem feindlichen Klan durchgeführt, den Nokhud.\n\nIhr nächster Außenposten liegt gleich an dieser Straße und ist der wahrscheinlichste Ort, an den sie die gefangenen Tauren bringen.\n\nDie Aufgabe ist einfach: Rettet die Gefangenen. Wir wissen nicht, wie viele es sind oder wie lange sie schon hier sind, deswegen müssen wir uns beeilen.\n\nIch spreche aus Erfahrung, wenn ich sage, dass Zentauren ihre Gefangenen nicht sehr lange behalten.", sourceObjective = "Rettet 6 Windtotemgefangene.", completion = "Wir haben das Lager durchsucht und gerettet, wen wir konnten, aber Bovan befindet sich nicht unter den Gefangenen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72600] = { id = 72600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine ordentliche Shikaarverabschiedung", description = "Wir sind hier, um die gefangenen Tauren zu befreien, aber ich habe eine persönliche Bitte.\n\nDer Ort, den wir angreifen, war früher meine Heimat. Die Nokhud haben ihn durch einen Überraschungsangriff während des Bürgerkriegs eingenommen.\n\nNehmt diese Banner der Shikaar. Wenn Ihr einen Nokhud oder einen ihrer Verbündeten tötet, so platziert ein Banner in der Leiche. Ich möchte eine Nachricht hinterlassen... falls sie weiter unsere Heimat besetzen, werden sie mit Blut dafür zahlen.", sourceObjective = "Rammt ein Banner der Shikaar in 15 getötete Zentauren der Nokhud oder ihre Verbündete.", progress = "Wie viele Banner habt Ihr aufgestellt?", completion = "Ich habe die Banner überall im Hochland verteilt gesehen. Es wird das Geschehene nicht ändern, aber es hat mir ein Lächeln ins Gesicht gezaubert.", sourceObjectiveStatus = "unverified-source-field" }
quests[72601] = { id = 72601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bovans letzte Hoffnung", description = "Wenn Bovan nicht hier ist, könnten die Nokhud ihn überall hingebracht haben. Wir haben vielleicht noch eine Möglichkeit, ihn zu finden, aber es ist weit hergeholt.\n\nWir haben immer noch Bovans Halskette. Einem der Mystiker der Ohn'ir ist es vielleicht möglich, damit seinen Standort wahrzusagen. Ich habe von diesem Ritual bisher nur gehört, ich habe also keine Ahnung, ob es funktionieren kann.\n\nGeht zu den Quellen von Ohn'iri und sucht nach Boku. Ich bin sicher, es wird ihm eine Freude sein, uns zu helfen.\n\nBaine und ich werden dafür sorgen, dass die Tauren, die wir gerettet haben, sicher zurückkehren. Wir treffen Euch dann bei den Quellen von Ohn'iri.", sourceObjective = "Find Boku bei den Quellen von Ohn'iri.", completion = "Tomul hat mir schon gesagt, was Ihr braucht!", sourceObjectiveStatus = "unverified-source-field" }
quests[72602] = { id = 72602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein optimistischer Mystiker", description = "Ich bin sicher, dass ich diesen Bovan Windtotem finden kann. Aber ich benötige dafür ein paar Gegenstände von Euch.\n\nZuerst brauche ich einige Blumen, welche am Ursprung der Quellen wachsen. Sie haben die speziellen Eigenschaften, nach denen wir suchen.\n\nDann brauche ich das Herz eines Salamanthers. Ein stärkeres Herz wird unsere Chancen erhöhen... sucht nach dem stärksten, das Ihr finden könnt.\n\nDie übrigen Materialien kann ich selbst einsammeln.", sourceObjective = "Sammelt ein starkes Salamantherherz und 8 Geysirblumen.", progress = "Habt Ihr alles gefunden?", completion = "Ja, das sollte genügen! Da Euer Freund die Quellen nicht betreten möchte, habe ich mich hier eingerichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[72603] = { id = 72603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wert der Worte", description = "Lasst mich nur gerade diese Blumen zerreiben... und dann sind wir soweit!\n\nNehmt diese Gegenstände und platziert sie in dem Räuchergefäß. Zusammen mit Bovans Halskette kann ich Ohn'ahra bitten, uns dabei zu helfen, ihn zu finden.\n\nMit etwas Glück wird sie uns eine Vision zukommen lassen.", sourceObjective = "Platziert die Gegenstände in dem Räuchergefäß und erlebt die Vision.", progress = "Hoffentlich funktioniert das.", completion = "Wenigstens habe ich einen verlässlichen Verbündeten. Habt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[72604] = { id = 72604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifelte Rettung", description = "Ich hätte wissen müssen, dass ich den Zentauren nicht trauen kann. Sie möge uns manchmal zur Hand gehen, aber sie würden nie auch nur das geringste Risiko für uns eingehen.\n\nKonzentrieren wir uns auf diese Angelegenheit. Wir können nicht zulassen, dass Bovan bei den Zentauren gefangen bleibt! Ich werde unverzüglich zur Festung Nokhudon aufbrechen.\n\nTrefft mich dort, so schnell es Euch möglich ist.", sourceObjective = "Trefft Baine Bluthuf vor der Festung Nokhudon.", completion = "Ihr seid da. Gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[72605] = { id = 72605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bovan Windtotem retten", description = "Die Zeit ist gegen uns, {name}. Wir müssen Bovan so schnell wie möglich finden!\n\nIn dieser Festung wimmelt es nur so von Zentauren. Unsere Suche wird schneller vorangehen, wenn wir uns aufteilen... und es wird leichter, an den Patrouillen vorbeizuschlüpfen.\n\nNehmt einen der Tränke, die ich mitgebracht habe. Er sollte Euch dabei helfen, unentdeckt zu bleiben. Hütet Euch aber vor den Kriegshunden der Nokhud. Wenn Tomul recht hat, werden sie Euch wahrscheinlich trotzdem wittern.\n\nSucht die Gegend nach Bovan ab. Falls Ihr ihn findet, bringt ihn raus. Wartet nicht auf mich.", sourceObjective = "Sucht in der Festung Nokhudon nach Bovan Windtotem.", completion = "Ich kam zu spät...", sourceObjectiveStatus = "unverified-source-field" }
quests[72606] = { id = 72606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rot sehen", description = "Nokhud, Gelkis, Magram, Kolkar. Sie sind alle gleich...\n\nSie verseuchen das Land. Sie ermorden mein Volk. Genug!\n\nIch werde der Bedrohung durch die Zentauren ein Ende setzen. Hier und jetzt!", sourceObjective = "Tötet Zentauren in der Festung Nokhudon.", progress = "Sie werden für das bezahlen, was sie getan haben.", completion = "<Nachdem er Dutzende von Zentauren niedergemetzelt hat, ist Baine sichtbar erschöpft. Er atmet schwer und ist von Verletzungen übersät.>\n\nJamoku... war für all das verantwortlich...\n\nIch werde ihn... nicht entkommen lassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[72607] = { id = 72607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alter Hass", description = "<Baine ist immer noch von seinen Kämpfen außer Atem.>\n\nIch werde nicht gehen... bevor Jamoku für das... was er getan hat... bezahlt...\n\nIch werde Bovan rächen... egal, was es kostet...", sourceObjective = "Tötet Jamoku.", completion = "Jamoku ist tot, wie so viele andere Zentauren. Wir haben Bovan und die anderen gerächt.\n\n<Baine verzieht das Gesicht, als er eine Wunde an der Seite seines Körpers berührt.>\n\nIm Nachhinein hätten wir es vielleicht nicht mit der gesamten Nokhud-Armee aufnehmen sollen. Doch zum Glück traf Tomul rechtzeitig ein, um für etwas mehr Chancengleichheit zu sorgen.\n\n<Baine wirft Tomul einen Blick zu.>\n\nEin Zentaur, der kämpft, um einen Tauren zu retten... Das hätte ich niemals für möglich gehalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[72609] = { id = 72609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fall abgeschlossen", description = "Ihr könnt von Glück reden, dass wir noch rechtzeitig eintrafen. Wir konnten die Verstärkung der Nokhud abfangen, als sie sich anschickte, Euch während Eures Kampfes mit Jamoku zu flankieren.\n\nWir haben in dieser Schlacht zwei unserer Leute verloren. Wenigstens wurden ihre Leichen bereits geborgen.\n\nDie Nokhud werden nicht lange brauchen, um sich zu sammeln und die Jagd auf uns zu eröffnen, um ihren Anführer zu rächen.\n\nWir müssen sofort aufbrechen. Geht nach Toghusuq, wo die Tauren ihr Lager aufgeschlagen haben. Wir treffen uns dann dort.", sourceObjective = "Trefft Späherin Tomul und Baine Bluthuf in Toghusuq.", completion = "Seit wir die Festung Nokhudon verlassen haben, hat Baine kaum ein Wort gesagt. Mir war nicht klar, wie viel dieser Bovan ihm bedeutet hat.\n\nIch werde nach seiner Beerdigung jedenfalls nach Maruukai zurückkehren. Der Befehl meines Khans wurde erfüllt, auch wenn er sich ein anderes Ergebnis erhofft hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[72611] = { id = 72611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loslassen", description = "Die Shikaar haben zwei aus ihren eigenen Reihen während der Schlacht verloren. Alle Verstärkungen Tomuls... Sie haben sich aus eigenen Stücken freiwillig zur Hilfe gemeldet.\n\nIch... Ich habe vieles zu überdenken.\n\nNach der Unterredung mit den Shikaar haben wir beschlossen, unsere Toten gemeinsam zu ehren. Aus diesem Anlass haben wir unsere Begräbnisriten zu einer Zeremonie vereint.\n\nEs wäre uns eine Ehre, wenn Ihr bleiben und daran teilnehmen könntet.", sourceObjective = "Sprecht mit Baine Bluthuf über die Beisetzung.", progress = "Diese Zentauren... Möge die Erdenmutter sie umarmen.", completion = "Bovan ist tot, aber seine Leute sind noch hier. Warum hat er sie hierher gebracht? Was hat er in seinen Visionen gesehen?\n\nDie Windtotems waren schon immer Nomaden. Hat er vielleicht endlich ein Zuhause für sie gefunden?\n\nOder... wusste er, was mit den Zentauren geschehen würde? Hat er uns hierher gebracht, um Frieden mit ihnen zu schließen? Oder um den Hass aus unseren eigenen Herzen zu tilgen?\n\nIch weiß nur eines ganz sicher: Ich muss weiter nach seinen Idealen leben. Nur so kann ich sein Leben und sein Andenken ehren.", sourceObjectiveStatus = "unverified-source-field" }
