quests[72637] = { id = 72637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Dracheninseln", sourceObjective = "Abenteurer, Eure Unterstützung war unserer Gemeinschaft und unserem Volk eine gewaltige Hilfe. Wir haben einige zusätzliche Vorräte für Euch aufbewahrt, in der Hoffnung, dass Ihr uns weiterhin helfen könnt! Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[72638] = { id = 72638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Dracheninseln", sourceObjective = "Freund, Eure Unterstützung war unserer Gemeinschaft und unserem Volk eine gewaltige Hilfe. Wir haben einige zusätzliche Vorräte für Euch aufbewahrt, in der Hoffnung, dass Ihr uns weiterhin helfen könnt!", sourceObjectiveStatus = "unverified-source-field" }
