quests[72640] = { id = 72640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Dracheninseln", sourceObjective = "Ah, unsere Wege kreuzen sich erneut, {name}. Ich bin froh, dass Ihr sicher zu uns zurückgekehrt seid. Eure Taten haben Euch in Iskaara Ehre eingebracht. Bitte, nehmt diese Vorräte zum Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[72641] = { id = 72641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Dracheninseln", sourceObjective = "Ah, unsere Wege kreuzen sich erneut, {name}. Ich bin froh, dass Ihr sicher zu uns zurückgekehrt seid. Eure Taten haben Euch in Iskaara Ehre eingebracht. Bitte, nehmt diese Vorräte zum Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[72642] = { id = 72642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Dracheninseln", sourceObjective = "Ah, unsere Wege kreuzen sich erneut, {name}. Ich bin froh, dass Ihr sicher zu uns zurückgekehrt seid. Eure Taten haben Euch in Iskaara Ehre eingebracht. Bitte, nehmt diese Vorräte zum Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[72643] = { id = 72643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Dracheninseln" }
quests[72644] = { id = 72644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dringende Angelegenheit", description = "Hallo, {name}. Mir wurde gesagt, ich soll Euch diesen Brief geben. Der Bote meinte, es wäre dringend.\n\nDas Wappen darauf sieht nach dem des SI:7 aus. An Eurer Stelle würde ich das sofort lesen.", sourceObjective = "Trefft Euch mit Meister Mathias Shaw auf dem äußeren Wall hinter der Burg Sturmwind.\n\nBereitgestellter Gegenstand:", completion = "Gut, dass Ihr da seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[72646] = { id = 72646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funken des Lebens: Küste des Erwachens", description = "Könnt Ihr den süßen Duft des Abenteuers im Wind riechen?\n\nDie Küste des Erwachens läuft vor Energie und Leben fast über. Macht Euch auf und holt Euch ein Stück vom Kuchen!", sourceObjective = "Sammelt 100 Funken des Lebens an der Küste des Erwachens, während Ihr im Kriegsmodus seid.", progress = "Die Lebensbecken sollen um diese Jahreszeit schön sein.", completion = "Habt Ihr etwas Nützliches gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[72647] = { id = 72647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funken des Lebens: Ebenen von Ohn'ahra", description = "Die Ebenen von Ohn'ahra sprudeln geradezu über vor Energie und die Lande wimmeln nur so von Wildtieren, {name}.\n\nEs ist Zeit, sich der Jagd anzuschließen, den Geschenken der Natur zu frönen und nach Ruhm zu streben.", sourceObjective = "Sammelt 100 Funken des Lebens auf den Ebenen von Ohn'ahra, während Ihr im Kriegsmodus seid.", progress = "Wie verläuft die Jagd?", completion = "Das war prächtig, findet Ihr nicht auch?", sourceObjectiveStatus = "unverified-source-field" }
quests[72648] = { id = 72648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funken des Lebens: Azurblaues Gebirge", description = "Die Gezeiten sind gekommen und haben ein Geschenk des Lebens mit sich ins Azurblaue Gebirge gebracht.\n\nEs ist Zeit für Freunde, Familie, gutes Essen und das Schmieden neuer Geschichten.", sourceObjective = "Sammelt 100 Funken des Lebens im Azurblauen Gebirge, während Ihr im Kriegsmodus seid.", progress = "Probiert die Suppe, während Ihr unterwegs seid.", completion = "Seid Ihr auf Gnolle gestoßen?", sourceObjectiveStatus = "unverified-source-field" }
quests[72649] = { id = 72649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funken des Lebens: Thaldraszus", description = "Thaldraszus pulsiert mit den erneuerten Energien der Dracheninseln.\n\nRaus mit Euch und nutzt das aus.", sourceObjective = "Sammelt bei aktivem Kriegsmodus 100 Funken des Lebens in Thaldraszus.", progress = "Einfach durch die Tür. Ihr könnt es nicht verfehlen.", completion = "Das Abkommen dankt Euch, zweifellos.", sourceObjectiveStatus = "unverified-source-field" }
quests[72650] = { id = 72650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warme Winde, warmes Wasser", description = "Kirygosa hat mir geschrieben, nachdem sie vor einigen Jahren das Schlingendorntal verlassen hat. Sie meinte, es sei wunderschön und mild, aber nicht besonders ruhig. Ich vermute und hoffe, dass sie in Pandaria ihren Frieden gefunden hat.\n\nWenn ich ganz ehrlich bin, sollte es mich nicht überraschen, dass sie dem Ruf der Inseln nicht gefolgt ist. Trotzdem ist es unsere Pflicht, sie aufzusuchen. Wenn ich noch ehrlicher bin, wäre das auch eine Ausrede für mich, sie wiederzusehen.\n\nLasst uns für eine Weile diesen kühlen Winden entkommen und den Jadewald besuchen.", sourceObjective = "Findet Kirygosa im Jadewald in Pandaria.", sourceObjectiveStatus = "unverified-source-field" }
quests[72651] = { id = 72651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karpfenpflege", description = "Die Karpfen bringen dem Dorf Glück und Frieden. Ihr Wohlbefinden spiegelt die Gesundheit des Dorfes wider.\n\nDie schimmernden Karpfen benötigen spezielles Futter aus Wurmmehl und Gemüsepaste. Das ist nicht so unangenehm wie es klingt, besonders nachdem wir es zu praktischen kleinen Würfeln formen.\n\nHier! Werft es einfach vorsichtig in ihrer Nähe ins Wasser.\n\nDie Teiche müssen auch gereinigt werden, also schöpft bitte jeglichen Schmutz ab, den Ihr finden könnt.", sourceObjective = "Füttert in Morgenblüte die Karpfen und reinigt ihre Teiche.", completion = "Alles erledigt? Habt Dank. Die Karpfen sind so hübsch, nicht? Ihre Schuppen schimmern fast wie die eines Drachens.", sourceObjectiveStatus = "unverified-source-field" }
quests[72652] = { id = 72652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Selbstfürsorge", sourceObjective = "Räumt Kirygosas Zuhause auf.", progress = "<Kalecgos schenkt Kirygosa seine volle Aufmerksamkeit.>", completion = "Oh, Ihr seid fertig? Habt vielen Dank. Kiry mag Euch, das sehe ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[72653] = { id = 72653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lokale Lieferungen", description = "Ich habe eine neue Blume in diesem Land gezüchtet. Sie lässt sich bereits sehr vielseitig einsetzen, aber die Dorfbewohner und ich sind immer noch dabei, ihre verschiedenen Verwendungszwecke zu verfeinern.\n\nIch habe heute erst den neuesten Schwung geerntet. Helft Ihr mir dabei, sie auszuliefern?", sourceObjective = "Liefert wilde blaue Ferne an die Dorfbewohner von Morgenblüte aus.", completion = "Wunderbar! Ach ja, wenn Ihr Blumen mögt, würde ich Euch gerne ein paar von meiner nächsten Ernte geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[72654] = { id = 72654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf, auf und nach Hause", sourceObjective = "Fliegt mit Kirygosa zu ihr nach Hause.", completion = "Da wären wir.", sourceObjectiveStatus = "unverified-source-field" }
quests[72655] = { id = 72655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Getränk mit Kalecgos", description = "<Kalecgos verstummt für einen Moment mit einem wehmütigen Blick.>\n\nIch würde Nozdormu bitten, uns dabei zu helfen, uns die Zeit zu vertreiben, aber er würde mir sagen, dass ich das alleine schaffen sollte.\n\nNun... Zum Betrunkenen Ho-zen. Wenn Kiry ihn uns empfiehlt, lasst uns gehen!", sourceObjective = "Trinkt etwas mit Kalecgos im Betrunkenen Ho-zen.", progress = "Peiji Zapfgold hat mir das perfekte Gebräu für die Kameradschaft empfohlen. Heißen Gerstentee! Bitte, nehmt Euch.", completion = "Das war eine dringend notwendige Pause.", sourceObjectiveStatus = "unverified-source-field" }
quests[72656] = { id = 72656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterquell", description = "Haleh, die Matrone des Protektorats, verwaltet Winterquell. Selbst nachdem der machthungrige Magier Umbranse besiegt ist, findet und beseitigt sie weiterhin sämtliche Gefahren in ihrer Heimat. Sie ist Malygos' letzte lebende Gefährtin und bewahrt unermüdlich sein Vermächtnis als Hüterin der Magie.\n\nIhre Rückkehr würde den blauen Drachenschwarm immens verstärken.", sourceObjective = "Sprecht mit Sindragosa, um mehr zu erfahren.", completion = "Ich habe Haleh seit meinem Erwachen im Auge behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[72657] = { id = 72657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Beschützerin der Magie", description = "Ich bin Haleh gegenüber sehr neugierig, da sie eine der letzten lebenden Gefährtinnen Malygos' ist. Ich bin dankbar dafür, dass sie Malygos in seiner Zeit der Not beigestanden hat.\n\nIch gebe zu, dass ich ihr lange hinterherspioniert habe. Sie ist ein blauer Drache durch und durch. Sie ist fleißig, stolz und unvergleichbar vorsichtig, wenn es um Magie geht. \n\nIch habe das Gefühl, am besten dafür geeignet zu sein, sie aufzusuchen und mit ihr über den Ruf der Inseln zu reden. Nehmt mein Portal, wenn Ihr bereit seid. Wir treffen uns dort.", sourceObjective = "Findet Haleh in Winterquell in Kalimdor.", completion = "Gebt Euch zu erkennen, Eindringlinge!", sourceObjectiveStatus = "unverified-source-field" }
quests[72658] = { id = 72658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugsteine", description = "Ihr seid mir direkt ins Auge gefallen, als Ihr Loamm betreten habt, Champion! Sieh sich nur einer diese glänzende Ausrüstung an. Und ich kann spüren, dass Ihr... mehr wollt.\n\nIhr seid vielleicht schon einmal auf Flugsteine gestoßen. Mein Freund Cuzolth und ich wissen, wie man die Kräfte der Flugsteine dazu nutzen kann, seine Ausrüstung aufzuwerten.\n\nDieses Wissen haben wir mit unserem Netzwerk an Aufwertungsspezialisten geteilt. Jeder von ihnen kann Euch ganz genau verraten, was Ihr braucht. Wenn Ihr genügend Flugsteine habt, kann Cuzolth es Euch auch sofort zeigen.", sourceObjective = "Besorgt 50 Flugsteine, indem Ihr einzigartige Kreaturen besiegt, Dungeons und Schlachtzüge bezwingt, Weltquests abschließt oder Schätze plündert. Sprecht danach mit Cuzolth und wertet einen Ausrüstungsgegenstand unter Einsatz von Flugsteinen auf.", completion = "Eure Ausrüstung glänzt nun noch etwas mehr, Champion! Ich bin immer darum bemüht, unsere Gemeinschaft zu stärken.\n\nBitte, akzeptiert diese Geschenke.", sourceObjectiveStatus = "unverified-source-field" }
quests[72659] = { id = 72659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versuchsobjekt", description = "Mit heute sind 41 Tage vergangen, an denen ich kein schädliches Artefakt gefunden habe. Außerdem kann ich voller Freude berichten, dass sich in Eurer Abwesenheit einige weitere als harmlos herausgestellt haben. Vielleicht nähert sich meine Suche in Winterquell ihrem Ende!\n\nWo ich gerade daran denke... Habt Ihr nicht irgendeine magische Fähigkeit? Oder zumindest genug Mut, mir dabei zu helfen, ein paar Artefakte zu testen?\n\nIhr müsst nicht nervös sein. Keines davon wird bleibende Schäden hinterlassen. Um Artefakte mit derart gefährlicher Macht haben wir uns in meinem ersten Jahr hier gekümmert.", sourceObjective = "Testet die Artefakte Flaschengeist, eisiges Buch und linker Stiefel.", progress = "Lasst Euch Zeit, {name}... nur noch ein paar hundert mehr.", completion = "Es scheint, als hätten drei von drei nur eine geringe magische Wirkung gehabt. Das sind wahrlich großartige Neuigkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[72660] = { id = 72660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uhurplötzlich", description = "Während Ihr gearbeitet habt, habe ich mir die totemischen Ruinen angesehen, die Ihr besorgt habt. Der Versteckte Hain hatte schon immer etwas Seltsames an sich. Früher war er dicht von harmlosen weißen Hasen bevölkert. Heute finden sich dort nur noch wahnsinnige Eulkin und seltsame Totems...\n\nIch habe die Teile zusammengesetzt. Es ist kein Meisterwerk, aber hoffentlich bekommen wir aus dem Ergebnis einen stärkeren magischen Effekt.\n\nVielleicht wachsen uns sogar Fell und Federn. Man sollte meinen, dass ich als blauer Drache die Kälte mag. Ich hasse die Kälte.", sourceObjective = "Testet das wiederhergestellte Eulkintotem.", progress = "Ich kann mich gar nicht an das letzte Mal erinnern, als ich richtige Hilfe hatte. Vielen Dank.", completion = "Natürlich, was habe ich erwartet?", sourceObjectiveStatus = "unverified-source-field" }
quests[72661] = { id = 72661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Wyrme tut allen gut", description = "Oh je. Ich habe eine Idee. Sprecht mit mir, sobald Ihr bereit seid.", sourceObjective = "Arbeitet mit Sindragosa zusammen, um Haleh aufzumuntern.", progress = "Ich befürchte, Haleh konnte keine angemessene Ruhe finden.", completion = "Ab und an brauchen wir nur mal wieder eine Kostprobe der einfachen Dinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[72662] = { id = 72662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte auffüllen", description = "Die Nokhud greifen seit einer Weile Außenseiter an, die die Ebenen betreten. Das hier ist zweifellos ihr Werk.\n\nDieser Überlebende sagt, dass bei dem Überfall beinahe ihre gesamten Nahrungsvorräte zerstört wurden. Wir sollten versuchen zu helfen.\n\nSammeln wir Fleisch von den Wildtieren um das Wasserloch. Das sollte ausreichen, um ihre dringendsten Bedürfnisse abzudecken.", sourceObjective = "Sammelt 40 Stücke Ebenenfrischfleisch in der Gegend rund um Toghusuq.", progress = "Wie viele habt Ihr eingesammelt?", completion = "Gut, das sollte genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72663] = { id = 72663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nadelholzspur", description = "Wenn Bovan weder tot noch hier ist, dann ist er entweder noch da draußen... oder er wurde gefangen genommen. Nach Tomuls Nachricht zu urteilen, befürchte ich Letzteres.\n\nDie Windtotems sind für den Moment sicher, aber mit der allgegenwärtigen Gefahr eines neuen Angriffs kann ich niemanden für die Suche nach Bovan entbehren.\n\nWie es aussieht, liegt es an uns. Gehen wir zum Nadelholzposten.", sourceObjective = "Trefft Euch mit Tomul und Baine am Nadelholzposten.", completion = "Tomul wollte, dass ich in ihrem Lager auf Euch warte, aber ich... habe dies höflich abgelehnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72664] = { id = 72664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eier im Überfluss", sourceObjective = "Trefft Amella beim Rubinlebensschrein an der Küste des Erwachens.", completion = "Danke, dass Ihr gekommen seid, {name}. Bald werden uns die Welpen vollkommen überwältigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72665] = { id = 72665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weisheit des Welpenhüters", description = "Unsere Eipfleger berichten, dass ein weiteres Gelege bald schlüpfen wird. Üblicherweise würde ein Welpenhüter jeden neu geschlüpften Drachen nehmen und mit dessen Schwarm aufziehen. Aber nicht alle Drachenbrut ist zum Leben eines Welpenhüters berufen, und wir sind zu wenige.\n\nSammelt die Weisheiten der Welpenhüter jedes Schwarms im Garten unter dem Lebensschrein. Agapanthus, ein erfahrener Welpenhüter des blauen Drachenschwarms, hat seine Dienste als Leiter der Krippe \"Kleinschuppe\" angeboten. Aber er wird Eure Hilfe brauchen.", sourceObjective = "Sprecht mit Welpenhütern im Garten der Rubinlebensbecken.", completion = "Amella sagte, ich sollte Euch aufsuchen. Ich wurde angewiesen, Agapanthus in der Krippe zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72666] = { id = 72666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krippendirektor Agapanthus", description = "Amella hat mir von den kommenden Welpen und der Krippe erzählt. Wusstet Ihr, dass Agapanthus ein bekannter Welpenhüter ist? Ich hörte, er hätte Dämonen zurückgeschlagen, während er Welpen aufzog! \n\nWenn er so großartig ist, wie sie sagen, habe ich viel von ihm zu lernen. Ich habe gerade erst meine Berufung erhalten, aber ich werde helfen, wo ich kann.\n\nDie Krippe \"Kleinschuppe\" ist in Valdrakken. Ich werde meine Habseligkeiten sammeln und Euch und Agapanthus dort treffen.", sourceObjective = "Trefft Agapanthus in der Krippe \"Kleinschuppe\" in Valdrakken.", completion = "Lasztak sagte mir gerade, wie eifrig er als Welpenhüter des roten Schwarms lernt. Mein Wissen stützt sich vor allem auf Erfahrung. Und Ihr...\n\n<Agapanthus seufzt und kratzt sich am Kinn.>\n\nWir müssen einen Lehrplan erstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72667] = { id = 72667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Happenrennen", description = "Die Welpen, die die Krippe besuchen, essen bei ihrem Aufenthalt Happen. Viele Happen.\n\nWenn hier regelmäßig Welpen bleiben sollen, werden wir noch mehr Verpflegung brauchen, um ihren endlosen Hunger zu stillen.\n\nHier ist eine Liste mit Essen, dass die Welpen in letzter Zeit besonders mögen. Ich habe auch etwas für Sir Pringisch bestellt, also besorgt das bitte auch.", sourceObjective = "Sammelt Happen von Verkäufern in Valdrakken.", progress = "So war es in Azsuna auch. Alle Welpen lieben Käse und Salzkekse.", completion = "Das war ein beeindruckendes erstes Happenrennen, {name}. Hoffentlich werden die Welpen diese Happen weiterhin mögen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72668] = { id = 72668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nahrhafte Umgebung", description = "Junge Welpen achten manchmal nicht besonders gut darauf, wie sie ihren Lebensraum behandeln. Die Krippe ist mehr oder weniger jeden Tag unter Belagerung!\n\nHelft in der Krippe beim Aufräumen. Die neuen Welpen brauchen ein ordentliches Umfeld.\n\nIch werde nicht zulassen, dass auch nur eine Klaue auf unpolierten Stein oder überwuchertes Gras gesetzt wird!", sourceObjective = "Helft in der Krippe \"Kleinschuppe\" beim Aufräumen.", completion = "Ich glaube, Ihr habt für heute genug aufgeräumt. Gute Arbeit, {name}.\n\nIch glaube, unser Lehrplan hat gut begonnen. Jetzt müssen wir auf die Welpen warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[72669] = { id = 72669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmvorräte", sourceObjective = "Grüße, {class}. Ihr habt Euren Wert gegenüber dem Valdrakkenabkommen bewiesen. Nehmt einige Vorräte als Unterstützung Eurer Sache. Enttäuscht uns nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[72670] = { id = 72670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zurückgelassenen", description = "Beim Versuch, ihr Zuhause gegen den Zorn des blauen Drachenschwarms zu verteidigen, haben die Magier von Shandaral die Seelen ihres Volkes zu ewigen kristallinen Qualen verdammt. \n\nNun wandern ihre Echos ziellos umher und durchleben die Verdammnis ihrer Zivilisation seit über zehntausend Jahren immer wieder aufs Neue.\n\nIch habe herausgefunden, dass manche dieser Schemen noch einen Funken Bewusstsein besitzen. Vielleicht lassen sie mit sich reden und sich davon überzeugen, dem Morast ihrer eigenen uralten Angst zu entkommen, um endlich weiterziehen zu können.", sourceObjective = "Beruhigt die rastlosen Echos von Shandaral.", completion = "Aus diesem kristallinen Gefängnis gibt es kein leichtes Entkommen. Mit etwas Glück wird unsere Arbeit die Geister, die noch hier verweilen, jedoch ein wenig Frieden finden lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72671] = { id = 72671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmvorräte", sourceObjective = "Grüße, {class}. Ihr habt Euren Wert gegenüber dem Valdrakkenabkommen bewiesen. Nehmt einige Vorräte als Unterstützung Eurer Sache. Enttäuscht uns nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[72672] = { id = 72672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmvorräte", sourceObjective = "Grüße, {class}. Ihr habt Euren Wert gegenüber dem Valdrakkenabkommen bewiesen. Nehmt einige Vorräte als Unterstützung Eurer Sache. Enttäuscht uns nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[72673] = { id = 72673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmvorräte", sourceObjective = "Grüße, {class}. Ihr habt Euren Wert gegenüber dem Valdrakkenabkommen bewiesen. Nehmt einige Vorräte als Unterstützung Eurer Sache. Enttäuscht uns nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[72674] = { id = 72674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein zersplittertes Vermächtnis", description = "Der Kristallfokus zerbrach unter der zu hohen Belastung, der er durch Shandarals leichtsinnige Verwendung ausgesetzt war. Seine Fragmente sind im kristallinen Permafrost verstreut.\n\nIch kann den Fokus wiederherstellen, aber Ihr müsst mir genug von diesen Splittern bringen, mit denen ich arbeiten kann. Ihr solltet sie in den Kristallhaufen finden, die in der ganzen Gegend verteilt sind.\n\nNehmt Euch in Acht, {class}. In diesen Splittern könnten noch immer Erinnerungen der Magier an diesen schicksalhaften Tag stecken.", sourceObjective = "Sammelt die Fragmente des Kristallfokus.", progress = "Malygos' Wut nährte Shandarals Verzweiflung. Jetzt ist das Versagen unseres Schwarms auf ewig in Kristall zur Schau gestellt.", completion = "Malygos war der Überzeugung, dass wir alleine dazu in der Lage wären, die unzähligen Wahrheiten des Arkanen zu bewahren. Sein und unser Versäumnis, das Potenzial der Sterblichen in Betracht zu ziehen, führte zu der Tragödie, die Ihr hier sehen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72675] = { id = 72675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbotene Insel 1/2" }
