quests[72678] = { id = 72678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbotene Insel 1/4" }
quests[72679] = { id = 72679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein arkanes Requiem", description = "Die Zeit ist gekommen, {name}. Mit Eurer Hilfe konnten wir die meisten rastlosen Echos von Shandaral bezwingen. Es verbleiben jedoch noch einige, deren Zorn und Trauer zu heiß brennen, um sie mit Worten allein zu löschen.\n\nMit den von Euch gesammelten Splittern konnte ich ein Duplikat des Kristallfokus nachbauen, der Shandaral ins Verderben gestürzt hat. Wenn Ihr ihn hier einsetzt, sollte es die gebundenen Geister zum Vorschein bringen und uns die Möglichkeit geben, ihnen die letzte Ruhe zu gewähren.\n\nSeid wachsam. Ich kann nicht sagen, auf welche Art sich ihre lang gehegten Sorgen manifestieren werden.", sourceObjective = "Gewährt den Echos von Shandaral die letzte Ruhe.", progress = "Das wird kein glückliches Ende nehmen. Aber es wird ein Ende haben.", completion = "Endlich wurde die Magie, die diese gequälten Erinnerungen an diese Ruinen gebunden hat, gebrochen.\n\nEs wird noch etwas dauern, bis die schwächeren Echos sich endgültig auflösen. Jetzt, wo ihre Quelle jedoch gebannt ist und die Reliktfragmente entfernt sind, werden die Erinnerungsfragmente, die noch hier gefangen sind, endlich von ihren Qualen erlöst.", sourceObjectiveStatus = "unverified-source-field" }
